INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('3f1e915e-173b-53a1-9156-9c71a88976eb', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 7, 7, 'A metal rod 0.20 m long moves at 5.0 m s⁻¹ at right angles to a uniform field of 0.15 T. Calculate the e.m.f. induced across its ends.', NULL, 1, 'numeric'::answer_type, '0.15', 'V', false, NULL, false, NULL, 'E = BLv = 0.15 × 0.20 × 5.0 = 0.15 V. Mark scheme (2 marks). C1: E = BLv. A1: E = 0.15 V.', 2),
('49ecc4f0-29ee-5042-b1da-7dde2d156141', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 8, 8, 'What is needed for an e.m.f. to be induced in a coil?', NULL, 1, 'multiple_choice'::answer_type, 'A change in the magnetic flux linking the coil', NULL, false, NULL, false, NULL, 'Only a changing flux linkage induces an e.m.f. Mark scheme (1 mark). B1: C (A change in the magnetic flux linking the coil).', 1),
('8e6192ff-294d-5c6a-be5f-f5885c2db6d3', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 9, 9, 'A magnet is pushed into a coil connected to a meter. It is then pushed in faster. What happens to the meter reading?', NULL, 1, 'multiple_choice'::answer_type, 'It is larger', NULL, false, NULL, false, NULL, 'The flux changes more quickly, so the induced e.m.f. is larger. Mark scheme (1 mark). B1: A (It is larger).', 1),
('2efb3c1d-3246-5718-9cfb-49297d8d68db', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 10, 10, 'A 0.40 m rod moves at right angles to a field of 0.050 T. Calculate the speed needed to induce an e.m.f. of 0.10 V.', NULL, 1, 'numeric'::answer_type, '5', 'm s⁻¹', false, NULL, false, NULL, 'v = E/(BL) = 0.10 ÷ (0.050 × 0.40) = 5.0 m s⁻¹. Mark scheme (2 marks). C1: rearranged E = BLv. A1: v = 5.0 m s⁻¹.', 2),
('cf757b44-0643-5912-a35a-f95d056a8963', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 11, 11, 'A magnet is pushed into a coil south pole first instead of north pole first, at the same speed. What happens to the induced e.m.f.?', NULL, 1, 'multiple_choice'::answer_type, 'It has the same size but the opposite direction', NULL, false, NULL, false, NULL, 'Reversing the field reverses the direction of the flux change. Mark scheme (1 mark). B1: D (It has the same size but the opposite direction).', 1),
('8a13c71e-1c54-52a9-9a62-50dc38f76b5c', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 12, 12, 'An aircraft with a wingspan of 30 m flies horizontally at 250 m s⁻¹ where the vertical component of the Earth''s field is 4.0 × 10⁻⁵ T. Calculate the e.m.f. between its wing tips.', NULL, 1, 'numeric'::answer_type, '0.3', 'V', false, NULL, false, NULL, 'E = BLv = 4.0 × 10⁻⁵ × 30 × 250 = 0.30 V. Mark scheme (2 marks). C1: E = BLv with vertical component. A1: E = 0.30 V.', 2),
('77fb2f12-0a52-54aa-9ac5-97b6e2f1add0', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 13, 13, 'Which change would increase the e.m.f. induced when a magnet moves into a coil at a fixed speed?', NULL, 1, 'multiple_choice'::answer_type, 'Using a coil with more turns', NULL, false, NULL, false, NULL, 'E is proportional to the number of turns N. Mark scheme (1 mark). B1: B (Using a coil with more turns).', 1),
('13939a35-ea44-554d-b9e6-3c99f2542124', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 14, 14, 'The flux through each turn of a 400-turn coil drops by 3.0 × 10⁻⁴ Wb over 0.15 s. Calculate the average induced e.m.f.', NULL, 1, 'numeric'::answer_type, '0.8', 'V', false, NULL, false, NULL, 'E = NΔΦ/Δt = 400 × 3.0 × 10⁻⁴ ÷ 0.15 = 0.80 V. Mark scheme (2 marks). C1: E = NΔΦ/Δt. A1: E = 0.80 V.', 2),
('0c508944-a925-52fd-a71b-e08375d68e35', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 15, 15, 'A straight wire moves along the direction of a uniform magnetic field. What e.m.f. is induced across it?', NULL, 1, 'multiple_choice'::answer_type, 'None', NULL, false, NULL, false, NULL, 'It does not cut any field lines, so no flux is swept out. Mark scheme (1 mark). B1: C (None).', 1),
('191cc3f0-59fd-5432-b75f-7881504f4b2d', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 16, 16, 'A horizontal rod 0.50 m long falls at 3.0 m s⁻¹ through a horizontal field of 0.20 T at right angles to the rod. Calculate the e.m.f. across it.', NULL, 1, 'numeric'::answer_type, '0.3', 'V', false, NULL, false, NULL, 'E = BLv = 0.20 × 0.50 × 3.0 = 0.30 V. Mark scheme (2 marks). C1: E = BLv. A1: E = 0.30 V.', 2),
('6353e38c-fc26-51d1-b60b-21b1385b4a98', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 17, 17, 'A coil connected to nothing (an open circuit) has a magnet pushed into it. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'An e.m.f. is induced, but no current flows', NULL, false, NULL, false, NULL, 'An e.m.f. appears whenever flux changes; a current needs a complete circuit. Mark scheme (1 mark). B1: A (An e.m.f. is induced, but no current flows).', 1),
('7ca3ac95-884c-5012-8b22-43298cf116d6', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 18, 18, 'A rod moving through a field has an induced e.m.f. of 12 mV. Its speed is doubled. What is the new e.m.f., in mV?', NULL, 1, 'numeric'::answer_type, '24 mV', 'mV', false, NULL, false, NULL, 'E ∝ v: 2 × 12 = 24 mV. Mark scheme (1 mark). A1: E = 24 mV.', 1),
('4c2636ed-afa9-5e6f-952e-1101186cbe48', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 19, 19, 'Faraday wound two coils on an iron ring. When was an e.m.f. induced in the second coil?', NULL, 1, 'multiple_choice'::answer_type, 'Only while the current in the first coil was being switched on or off', NULL, false, NULL, false, NULL, 'Only a changing current gives a changing flux in the ring. Mark scheme (1 mark). B1: D (Only while the current in the first coil was being switched on or off).', 1),
('547188c9-01ed-5529-ab7a-ef6014aaf0ea', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 20, 20, 'A 0.25 m rod moving at 8.0 m s⁻¹ at right angles to a field has an induced e.m.f. of 0.050 V. Calculate the flux density.', NULL, 1, 'numeric'::answer_type, '0.025', 'T', false, NULL, false, NULL, 'B = E/(Lv) = 0.050 ÷ (0.25 × 8.0) = 0.025 T. Mark scheme (2 marks). C1: B = E/(Lv). A1: B = 0.025 T.', 2),
('1dc53da5-b227-54ec-a59e-5038a5e1f325', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 21, 21, 'A flat coil moves sideways, without turning, inside a large region of uniform magnetic field. What e.m.f. is induced?', NULL, 1, 'multiple_choice'::answer_type, 'None, because the flux linkage stays constant', NULL, false, NULL, false, NULL, 'The same flux passes through the coil at every position. Mark scheme (1 mark). B1: B (None, because the flux linkage stays constant).', 1),
('a92854a4-a7a2-5640-a42f-da9a1e797ad8', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 22, 22, 'A 0.50 m rod moves at 6.0 m s⁻¹ through a 0.20 T field, with its velocity at 30° to the field lines (the rod is at right angles to both). Calculate the induced e.m.f.', NULL, 1, 'numeric'::answer_type, '0.3', 'V', false, NULL, false, NULL, 'E = BLv sin θ = 0.20 × 0.50 × 6.0 × sin 30° = 0.30 V. Mark scheme (2 marks). C1: only the velocity component across the field. A1: E = 0.30 V.', 2),
('698076ca-9d3d-5fb9-99fb-2f1dab0d86a3', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 23, 23, 'A 0.30 m rod moves at 4.0 m s⁻¹ across a 0.50 T field on rails connected by a 2.0 Ω resistor. Ignoring other resistance, calculate the current.', NULL, 2, 'numeric'::answer_type, '0.3', 'A', false, NULL, false, NULL, 'E = BLv = 0.50 × 0.30 × 4.0 = 0.60 V. I = E/R = 0.60 ÷ 2.0 = 0.30 A. Mark scheme (3 marks). C1: E = BLv. C1: I = E/R. A1: I = 0.30 A.', 3),
('2346deaf-1b73-5bc1-9013-edd3691b96f0', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 24, 24, 'A train axle 1.4 m long moves at 30 m s⁻¹ where the vertical component of the Earth''s field is 4.0 × 10⁻⁵ T. Calculate the e.m.f. across the axle, in mV.', NULL, 2, 'numeric'::answer_type, '1.68 mV', 'mV', false, NULL, false, NULL, 'E = BLv = 4.0 × 10⁻⁵ × 1.4 × 30 = 0.00168 V. In mV: 0.001680 × 1000 = 1.68. Mark scheme (3 marks). C1: E = BLv. C1: conversion. A1: E = 1.68 mV.', 3),
('90d039fa-0975-5072-974a-64761e3266d7', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 25, 25, 'A bar magnet falls through a horizontal coil connected to a data logger. Which describes the e.m.f.–time graph?', NULL, 2, 'multiple_choice'::answer_type, 'Two pulses of opposite sign; the second is taller and narrower because the magnet is moving faster', NULL, false, NULL, false, NULL, 'Flux increases as it enters and decreases as it leaves; it accelerates as it falls. Mark scheme (3 marks). C1: opposite signs entering and leaving. C1: second pulse faster, larger. A1: C (Two pulses of opposite sign; the second is taller and narrower because the magnet is moving faster).', 3),
('12b5a78b-d95c-56da-ae18-7938844f8486', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 26, 26, 'A magnet is pushed into a 200-turn coil in 0.20 s, and the flux through each turn rises from zero to 3.0 × 10⁻⁵ Wb. Calculate the average induced e.m.f., in mV.', NULL, 2, 'numeric'::answer_type, '30 mV', 'mV', false, NULL, false, NULL, 'Δ(NΦ) = 200 × 3.0 × 10⁻⁵ = 6.0 × 10⁻³ Wb. E = 6.0 × 10⁻³ ÷ 0.20 = 0.030 V. In mV: 0.030 × 1000 = 30. Mark scheme (4 marks). C1: flux linkage. C1: E = Δ(NΦ)/Δt. C1: conversion. A1: E = 30 mV.', 4),
('a5117591-a100-5322-a4f2-366e7f1c1359', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 27, 27, 'A 0.40 m rod moves 0.50 m in 0.25 s at right angles to a 0.30 T field. Calculate the induced e.m.f.', NULL, 2, 'numeric'::answer_type, '0.24', 'V', false, NULL, false, NULL, 'Flux cut = BLd = 0.30 × 0.40 × 0.50 = 0.060 Wb. E = 0.060 ÷ 0.25 = 0.24 V. Mark scheme (3 marks). C1: flux cut. C1: ÷ time. A1: E = 0.24 V.', 3),
('0d176068-e57d-583e-aa79-646398cf10d6', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 28, 28, 'The length of a moving rod is doubled and its speed is halved, in the same field. What happens to the induced e.m.f.?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'E = BLv: doubling L and halving v leaves the product Lv, and so E, unchanged. Mark scheme (3 marks). C1: E = BLv. C1: product unchanged. A1: A (It stays the same).', 3),
('f95d6830-9889-5522-b96b-6b8b85a8688d', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 29, 29, 'A rod of length L rotating about one end at angular speed ω in a field B at right angles has an e.m.f. E = ½BωL². Calculate E for a 6.0 m helicopter blade at 30 rad s⁻¹ in a vertical field of 5.0 × 10⁻⁵ T.', NULL, 2, 'numeric'::answer_type, '0.027', 'V', false, NULL, false, NULL, 'E = ½BωL² = 0.5 × 5.0 × 10⁻⁵ × 30 × 6.0² = 0.0270 V. Mark scheme (3 marks). C1: formula. C1: substitution. A1: E = 0.0270 V.', 3),
('e24846cf-d408-52db-825e-72a26a65612f', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 30, 30, 'A rod moving across a field produces an e.m.f. of 0.60 V and is connected to a 2.0 Ω resistor. Calculate the power dissipated in the resistor.', NULL, 2, 'numeric'::answer_type, '0.18', 'W', false, NULL, false, NULL, 'P = E²/R = 0.60² ÷ 2.0 = 0.18 W. Mark scheme (4 marks). C1: current or P = V²/R. C1: substitution. B1: power comes from the work done moving the rod. A1: P = 0.18 W.', 4),
('e0bcd9a7-965a-5dec-854f-1f736c9a59e1', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 31, 31, 'Why is no e.m.f. induced in a coil that moves without rotating inside a uniform field?', NULL, 2, 'multiple_choice'::answer_type, 'The flux linkage of the coil does not change', NULL, false, NULL, false, NULL, 'E = rate of change of flux linkage, which is zero here. Mark scheme (3 marks). C1: E depends on change of NΦ. C1: NΦ constant. A1: D (The flux linkage of the coil does not change).', 3),
('6ce573b0-cd5c-5be4-9943-3b8e75a50fb2', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 32, 32, 'The flux linkage of a coil changes by 4.5 × 10⁻³ Wb in 0.090 s. Calculate the average induced e.m.f.', NULL, 2, 'numeric'::answer_type, '0.05', 'V', false, NULL, false, NULL, 'E = Δ(NΦ)/Δt = 4.5 × 10⁻³ ÷ 0.090 = 0.050 V. Mark scheme (3 marks). C1: E = Δ(NΦ)/Δt. C1: substitution. A1: E = 0.050 V.', 3),
('0b05834d-4c5a-5443-9c4f-79bfb4ea6e4b', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 33, 33, 'The flux through each turn of a coil changes by 2.4 × 10⁻⁵ Wb in 0.010 s, inducing an average e.m.f. of 0.12 V. Calculate the number of turns.', NULL, 2, 'numeric'::answer_type, '50', 'turns', false, NULL, false, NULL, 'N = EΔt/ΔΦ = 0.12 × 0.010 ÷ 2.4 × 10⁻⁵ = 50 turns. Mark scheme (3 marks). C1: rearranged. C1: value. A1: N = 50 turns.', 3),
('fe74be37-8e88-5ed8-8040-5f6e19528358', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 34, 34, 'In Faraday''s iron-ring experiment, the current in the first coil is steady. What is the reading on a meter connected to the second coil?', NULL, 2, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'A steady current gives a constant flux, so there is no change of flux linkage. Mark scheme (3 marks). C1: constant flux. C1: no e.m.f. A1: B (Zero).', 3),
('f0e1e9fd-2f05-5d30-a23e-d5cd54767c68', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 35, 35, 'A 0.50 m rod moves at right angles to a 0.80 T field. Calculate the speed needed for an e.m.f. of 1.0 V.', NULL, 2, 'numeric'::answer_type, '2.5', 'm s⁻¹', false, NULL, false, NULL, 'v = E/(BL) = 1.0 ÷ (0.80 × 0.50) = 2.5 m s⁻¹. Mark scheme (3 marks). C1: rearranged. C1: value. A1: v = 2.5 m s⁻¹.', 3),
('96b2a53e-f29a-5aaa-b2ce-6fd4ba6e8ddf', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 36, 36, 'Coil A has 100 turns of area A. Coil B has 200 turns of area A/2. They are in the same changing field. How do their induced e.m.f.s compare?', NULL, 2, 'multiple_choice'::answer_type, 'They are equal', NULL, false, NULL, false, NULL, 'E = NA dB/dt: 100A = 200 × A/2. Mark scheme (4 marks). C1: E = NA dB/dt. C1: NA equal. C1: equal e.m.f. A1: C (They are equal).', 4),
('4e0e4321-4d2b-52a2-b26b-93ef9c565762', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 37, 37, 'A space tether 20 km long moves at 7.5 km s⁻¹ at right angles to a field of 3.0 × 10⁻⁵ T. Calculate the e.m.f. along it.', NULL, 2, 'numeric'::answer_type, '4500', 'V', false, NULL, false, NULL, 'E = BLv = 3.0 × 10⁻⁵ × 20 × 10³ × 7.5 × 10³ = 4500 V. Mark scheme (3 marks). C1: units converted. C1: E = BLv. A1: E = 4500 V.', 3),
('6fc2acb2-0896-5d07-87f3-ba1da7496a6d', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 38, 38, 'A wire 0.10 m long is swung 0.050 m across a 0.60 T field in 0.020 s. Calculate the average e.m.f.', NULL, 2, 'numeric'::answer_type, '0.15', 'V', false, NULL, false, NULL, 'v = 0.050 ÷ 0.020 = 2.5 m s⁻¹. E = BLv = 0.60 × 0.10 × 2.5 = 0.15 V. Mark scheme (3 marks). C1: average speed. C1: E = BLv. A1: E = 0.15 V.', 3),
('2aa0de82-6fdc-5cfd-829d-e20aa6d3c676', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 39, 39, 'Which observation shows that the induced e.m.f. depends on the rate of change of flux?', NULL, 2, 'multiple_choice'::answer_type, 'Moving the magnet faster gives a larger meter deflection for the same movement', NULL, false, NULL, false, NULL, 'The same flux change in less time gives a larger e.m.f. Mark scheme (3 marks). C1: same flux change. C1: shorter time, larger e.m.f. A1: A (Moving the magnet faster gives a larger meter deflection for the same movement).', 3),
('1ea29139-c4c6-5732-a320-8bb00b7f49bb', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 40, 40, 'A metal rod 0.25 m long slides at a steady 4.0 m s⁻¹ along two rails joined by a 0.50 Ω resistor, at right angles to a field of 0.60 T. (a) Calculate the induced e.m.f. (b) Calculate the current. (c) Calculate the force needed to keep the rod moving at constant speed. (d) Show that the mechanical power equals the electrical power. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.18', 'N', false, NULL, false, NULL, '(a) E = 0.60 × 0.25 × 4.0 = 0.60 V. (b) I = 0.60 ÷ 0.50 = 1.2 A. (c) The current in the rod feels F = BIL = 0.60 × 1.2 × 0.25 = 0.18 N opposing the motion, so 0.18 N is needed. (d) Fv = 0.18 × 4.0 = 0.72 W and EI = 0.60 × 1.2 = 0.72 W. Mark scheme (6 marks). C1: E = BLv. C1: I = E/R. M1: opposing force BIL. C1: value. B1: Fv = EI. A1: F = 0.18 N.', 6),
('be723604-1b3c-55bf-b00a-8611863f8925', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 41, 41, 'An airliner with a wingspan of 60 m flies horizontally at 270 m s⁻¹ where the vertical component of the Earth''s field is 4.5 × 10⁻⁵ T. (a) Calculate the e.m.f. between the wing tips. (b) Explain why this e.m.f. cannot be used to light a lamp connected between the wing tips on board. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '0.729', 'V', false, NULL, false, NULL, '(a) E = 4.5 × 10⁻⁵ × 60 × 270 = 0.729 V. (b) The connecting wires move with the aircraft and have the same e.m.f. induced in them, so there is no net e.m.f. round the circuit. Mark scheme (5 marks). C1: vertical component. C1: E = BLv. B1: wires also cut field. B1: e.m.f.s cancel round loop. A1: E = 0.729 V.', 5),
('e6ac70d5-a5af-58cb-9cab-9f8499f304bc', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 42, 42, 'A magnet falls through a 500-turn coil. One e.m.f. pulse is roughly a triangle with a peak of 40 mV and a duration of 0.10 s. (a) Explain why the area under an e.m.f.–time graph equals the change in flux linkage. (b) Estimate the change in flux linkage during the pulse. (c) Calculate the change in flux through each turn, in µWb. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4', 'µWb', false, NULL, false, ARRAY['4e-6']::text[], '(a) E = d(NΦ)/dt, so ∫E dt = Δ(NΦ). (b) Area = 0.5 × 0.040 × 0.10 = 2.0 × 10⁻³ Wb. (c) ΔΦ = 2.0 × 10⁻³ ÷ 500 = 4.0 × 10⁻⁶ Wb. In µWb: 4.0 × 10⁻⁶ × 10⁶ = 4.0. Mark scheme (6 marks). B1: area = Δ(NΦ). C1: triangle area. C1: ÷ N. C1: conversion. M1: units V s = Wb. A1: ΔΦ = 4.0 µWb.', 6),
('a8d1f694-cf20-5399-8543-70643216a95a', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 43, 43, 'When the current in a primary coil is switched on, the flux through each turn of a 300-turn secondary coil rises from zero to 2.0 × 10⁻⁵ Wb in 5.0 ms. (a) Calculate the average e.m.f. induced in the secondary. (b) Explain why there is no e.m.f. once the primary current is steady. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '1.2', 'V', false, NULL, false, NULL, '(a) E = 300 × 2.0 × 10⁻⁵ ÷ 5.0 × 10⁻³ = 1.2 V. (b) A steady current gives a constant flux, so the flux linkage no longer changes. Mark scheme (5 marks). C1: Δ(NΦ). C1: Δt in s. C1: E. B1: no change, no e.m.f. A1: E = 1.2 V.', 5),
('95665f8a-c4cc-5b67-9b16-97f66c196674', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 44, 44, 'A copper disc of radius 0.10 m rotates at 50 revolutions per second about its axis, in a uniform field of 0.40 T parallel to the axis. The e.m.f. between centre and rim is E = ½BωR². (a) Calculate the angular speed. (b) Calculate the e.m.f. (c) Explain why this e.m.f. is steady, not alternating. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.6283', 'V', false, NULL, false, NULL, '(a) ω = 2π × 50 = 314 rad s⁻¹. (b) E = 0.5 × 0.40 × 314.2 × 0.10² = 0.628 V. (c) Each radius cuts the field at the same steady rate in the same sense, so the e.m.f. does not reverse. Mark scheme (6 marks). C1: ω = 2πf. C1: E formula. C1: substitution. B1: steady rate of cutting. B1: no reversal. A1: E = 0.628 V.', 6),
('3d72426b-be11-5cae-8607-bbdaf69eaf26', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 45, 45, 'A square coil of 20 turns and side 0.050 m is pulled at a steady 0.25 m s⁻¹ out of a region of uniform field 0.30 T, with its plane at right angles to the field. (a) Calculate the e.m.f. while one side is still in the field. (b) Calculate the time taken to leave the field. (c) Show that e.m.f. × time equals the change in flux linkage. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '0.075', 'V', false, NULL, false, NULL, '(a) E = NBLv = 20 × 0.30 × 0.050 × 0.25 = 0.075 V. (b) t = 0.050 ÷ 0.25 = 0.20 s. (c) Et = 0.075 × 0.20 = 0.015 Wb, and NBA = 20 × 0.30 × 0.050² = 0.015 Wb. Mark scheme (5 marks). C1: E = NBLv. C1: t = L/v. C1: Et. B1: equals NBA. A1: E = 0.075 V.', 5),
('e5efc193-a2a7-5490-ad4e-afc692f79d25', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 46, 46, 'A horizontal east–west rod 1.5 m long is dropped from rest. The Earth''s horizontal field is 1.8 × 10⁻⁵ T, at right angles to the rod. (a) Calculate the speed of the rod after 2.0 s. (b) Calculate the e.m.f. across it then, in mV. (c) Explain why the e.m.f. increases steadily during the fall. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.5297 mV', 'mV', false, NULL, false, NULL, '(a) v = gt = 9.81 × 2.0 = 19.6 m s⁻¹. (b) E = 1.8 × 10⁻⁵ × 1.5 × 19.62 = 5.30 × 10⁻⁴ V. In mV: 5.297 × 10⁻⁴ × 1000 = 0.530. (c) E ∝ v, and v increases uniformly with time. Mark scheme (6 marks). C1: v = gt. C1: E = BLv. C1: conversion. B1: E ∝ v. B1: uniform acceleration. A1: E = 0.530 mV.', 6),
('e2ddd16d-4f06-5a92-997f-50ec780d46ee', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 47, 47, 'A search coil of 500 turns and area 1.0 cm² lies face-on to a uniform field. It is turned over in 0.050 s, and the average e.m.f. is 0.12 V. (a) Explain why the change in flux linkage is 2NBA. (b) Calculate B. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.06', 'T', false, NULL, false, NULL, '(a) The flux linkage changes from +NBA to −NBA. (b) B = EΔt/(2NA) = 0.12 × 0.050 ÷ (2 × 500 × 1.0 × 10⁻⁴) = 0.060 T. Mark scheme (5 marks). B1: reversal gives 2NBA. C1: area in m². C1: rearranged. C1: value. A1: B = 0.060 T.', 5),
('1b41a785-052d-56d6-8e21-f800082d7593', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 48, 48, 'A rod 0.20 m long accelerates uniformly from rest across a field of 0.50 T. The induced e.m.f. rises steadily from 0 to 0.40 V in 2.0 s. (a) Calculate the speed of the rod at 2.0 s. (b) Calculate its acceleration. (c) Sketch, in words, the e.m.f.–time graph. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2', 'm s⁻²', false, NULL, false, NULL, '(a) v = E/(BL) = 0.40 ÷ (0.50 × 0.20) = 4.0 m s⁻¹. (b) a = 4.0 ÷ 2.0 = 2.0 m s⁻². (c) A straight line through the origin, because E ∝ v ∝ t. Mark scheme (5 marks). C1: v = E/(BL). C1: a = v/t. C1: value. B1: linear graph. A1: a = 2.0 m s⁻².', 5),
('69e1af53-831b-535f-a45e-7e195299ebca', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 49, 49, 'A rod 0.20 m long is moved at different speeds across a uniform field: v/m s⁻¹ = 1.0, 2.0, 3.0, 4.0 and E/V = 0.08, 0.16, 0.24, 0.32. (a) Describe the relationship. (b) Calculate the gradient of the E–v graph. (c) Calculate B. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.4', 'T', false, NULL, false, NULL, '(a) E ∝ v. (b) Gradient = (0.32 − 0.08) ÷ (4.0 − 1.0) = 0.080 V s m⁻¹. (c) Gradient = BL, so B = 0.080 ÷ 0.20 = 0.40 T. Mark scheme (5 marks). B1: proportional. C1: gradient. M1: gradient = BL. C1: value. A1: B = 0.40 T.', 5),
('e301acae-3914-5c60-a10c-a985a9d3d43e', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '677b6661-3e99-4229-b915-0bb8761b4eaf', 'a-level', '26.1', '9702 coursebook 26.1 · Observing induction', 50, 50, 'A 100-turn coil with a total resistance of 5.0 Ω has the flux through each turn changed by 4.0 × 10⁻⁴ Wb. (a) Show that the charge that flows is Q = Δ(NΦ)/R. (b) Calculate Q, in mC. (c) Explain why Q does not depend on how quickly the flux changes. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '8 mC', 'mC', false, NULL, false, NULL, '(a) I = E/R = (1/R) d(NΦ)/dt, so Q = ∫I dt = Δ(NΦ)/R. (b) Q = 100 × 4.0 × 10⁻⁴ ÷ 5.0 = 8.0 × 10⁻³ C. In mC: 8.0 × 10⁻³ × 1000 = 8.0. (c) A faster change gives a larger current for a shorter time; the product is the same. Mark scheme (6 marks). M1: I = E/R. B1: integrate to get Q. C1: substitution. C1: conversion. B1: rate cancels. A1: Q = 8.0 mC.', 6)
