('4f60dc39-24e4-5323-8ecc-5feb52f47cc0', '49ecc4f0-29ee-5042-b1da-7dde2d156141', 'A change in the magnetic flux linking the coil', 'C', true, 2),
('f66b4b99-f65d-5e3b-84e2-14228308472a', '49ecc4f0-29ee-5042-b1da-7dde2d156141', 'An iron core', 'D', false, 3),
