('789a04b5-50cc-541f-aa11-32e485d009eb', '8e6192ff-294d-5c6a-be5f-f5885c2db6d3', 'It is the same', 'C', false, 2),
('2cef60e8-e0d2-5544-996d-6c01583fd2ba', '8e6192ff-294d-5c6a-be5f-f5885c2db6d3', 'It is zero', 'D', false, 3),
('e9bca265-ddd9-5bee-805d-1c5118688e41', 'cf757b44-0643-5912-a35a-f95d056a8963', 'It doubles', 'A', false, 0),
