('2f58e08c-4ab8-5c4a-818b-494aa03212bf', 'cf757b44-0643-5912-a35a-f95d056a8963', 'It is the same in size and direction', 'C', false, 2),
('6b951346-0757-50a9-996d-7d4baad23a86', 'cf757b44-0643-5912-a35a-f95d056a8963', 'It has the same size but the opposite direction', 'D', true, 3),
('6db96694-832f-5bea-8e84-f159c3c5da9a', '77fb2f12-0a52-54aa-9ac5-97b6e2f1add0', 'Using a weaker magnet', 'A', false, 0),
('7ad35aed-cffd-5d41-85d8-93ddd2885201', '77fb2f12-0a52-54aa-9ac5-97b6e2f1add0', 'Using a coil with more turns', 'B', true, 1),
('bd15de08-6e1f-5e68-8917-ed9743f0f837', '77fb2f12-0a52-54aa-9ac5-97b6e2f1add0', 'Using fewer turns', 'C', false, 2),
('a102cf3c-a353-55bc-aa10-3883d7acaf4a', '77fb2f12-0a52-54aa-9ac5-97b6e2f1add0', 'Holding the magnet still', 'D', false, 3),
('593f6bd2-f4ee-5bbc-a373-422b1e499d3e', '0c508944-a925-52fd-a71b-e08375d68e35', 'BLv', 'A', false, 0),
('40a7264e-f67e-5c9f-9fd4-a1cb4a74fea5', '0c508944-a925-52fd-a71b-e08375d68e35', 'Half of BLv', 'B', false, 1),
('17e3077b-3854-5a3b-999d-53db5e55dc34', '0c508944-a925-52fd-a71b-e08375d68e35', 'None', 'C', true, 2),
('f596780f-c6fa-5217-9c08-d78f863955db', '0c508944-a925-52fd-a71b-e08375d68e35', 'It depends on the length only', 'D', false, 3),
('cf8fd625-57e3-52f9-8316-ab83a15cb9df', '6353e38c-fc26-51d1-b60b-21b1385b4a98', 'An e.m.f. is induced, but no current flows', 'A', true, 0),
('8830734a-c7cc-5a65-9d6c-4f74e580fd3f', '6353e38c-fc26-51d1-b60b-21b1385b4a98', 'A current flows, but no e.m.f. is induced', 'B', false, 1),
('edb8546e-5e3a-538f-a6c8-f2c868154fcc', '6353e38c-fc26-51d1-b60b-21b1385b4a98', 'Both an e.m.f. and a current are produced', 'C', false, 2),
('3f65ed65-cea7-553f-b07a-0f16934f83a2', '6353e38c-fc26-51d1-b60b-21b1385b4a98', 'Neither is produced', 'D', false, 3),
('efbecb3f-61cf-5006-8d1a-fac8aa5865ed', '4c2636ed-afa9-5e6f-952e-1101186cbe48', 'All the time the current in the first coil was steady', 'A', false, 0),
('bc2a9bbc-f596-574b-ad2e-6e5c5b45dfc8', '4c2636ed-afa9-5e6f-952e-1101186cbe48', 'Only when the ring was removed', 'B', false, 1),
('14c7bab8-454b-5edb-b374-98c8714036fe', '4c2636ed-afa9-5e6f-952e-1101186cbe48', 'Never', 'C', false, 2),
('206ea6c5-2c7b-5411-b0e9-6b18e9fa3eaf', '4c2636ed-afa9-5e6f-952e-1101186cbe48', 'Only while the current in the first coil was being switched on or off', 'D', true, 3),
('d57212f6-694a-53a6-9eb1-45c69ee3d4cd', '1dc53da5-b227-54ec-a59e-5038a5e1f325', 'A steady e.m.f.', 'A', false, 0),
('1b5696e5-ea6f-5fdd-8327-6c81023cc1b0', '1dc53da5-b227-54ec-a59e-5038a5e1f325', 'None, because the flux linkage stays constant', 'B', true, 1),
('24f3a7d0-aa9f-5911-93ff-001a7b483aad', '1dc53da5-b227-54ec-a59e-5038a5e1f325', 'An alternating e.m.f.', 'C', false, 2),
('5b540d8f-2d12-57dd-86e6-bf66d4db017c', '1dc53da5-b227-54ec-a59e-5038a5e1f325', 'An e.m.f. that grows with time', 'D', false, 3),
('0564b412-47d3-5090-8a98-6d1ad329a4e1', '90d039fa-0975-5072-974a-64761e3266d7', 'One pulse only', 'A', false, 0),
