('ebcde4be-b6af-5640-b01f-aed93c37d8ca', '90d039fa-0975-5072-974a-64761e3266d7', 'Two pulses of opposite sign; the second is taller and narrower because the magnet is moving faster', 'C', true, 2),
('0ce0f772-1567-5ed1-978b-5cce2e38dede', '90d039fa-0975-5072-974a-64761e3266d7', 'A steady e.m.f. while the magnet is inside', 'D', false, 3),
('971893ef-5142-5aea-bce6-e01786e9f689', '0d176068-e57d-583e-aa79-646398cf10d6', 'It stays the same', 'A', true, 0),
('82bf9162-2c47-53f8-9204-84a70ae8dd09', '0d176068-e57d-583e-aa79-646398cf10d6', 'It doubles', 'B', false, 1),
