('1b774b81-cb1b-50ae-b8f7-7a4dbca2af2d', '0d176068-e57d-583e-aa79-646398cf10d6', 'It quadruples', 'D', false, 3),
('274a41eb-8850-5ec4-b0f1-aba3218affe0', 'e0bcd9a7-965a-5dec-854f-1f736c9a59e1', 'The field is too weak', 'A', false, 0),
('d557296a-dcee-5eb8-ab2c-f4da082024da', 'e0bcd9a7-965a-5dec-854f-1f736c9a59e1', 'The coil has too few turns', 'B', false, 1),
('b41df612-0bf8-50bd-9e05-ecce1aea51bf', 'e0bcd9a7-965a-5dec-854f-1f736c9a59e1', 'The coil must be made of iron', 'C', false, 2),
('5ce76c83-d847-5b44-aae2-b8e10743ba14', 'e0bcd9a7-965a-5dec-854f-1f736c9a59e1', 'The flux linkage of the coil does not change', 'D', true, 3),
('380e89b0-9db5-56e8-9f2d-abaa96fbdd0c', 'fe74be37-8e88-5ed8-8040-5f6e19528358', 'A steady non-zero reading', 'A', false, 0),
('6fb73c4e-e02e-5122-b0cc-7e0ef05b092b', 'fe74be37-8e88-5ed8-8040-5f6e19528358', 'Zero', 'B', true, 1),
('cafe4614-27af-523d-a6f1-0c0af7c7b6ef', 'fe74be37-8e88-5ed8-8040-5f6e19528358', 'An alternating reading', 'C', false, 2),
('723930b4-23a5-56f0-bcdd-eefcc89f60fb', 'fe74be37-8e88-5ed8-8040-5f6e19528358', 'A reading that slowly increases', 'D', false, 3),
('9e252c2f-d958-5da6-addd-a5db9c24be87', '96b2a53e-f29a-5aaa-b2ce-6fd4ba6e8ddf', 'A has twice the e.m.f. of B', 'A', false, 0),
('f3805979-6602-58e0-b9cb-5821170760f8', '96b2a53e-f29a-5aaa-b2ce-6fd4ba6e8ddf', 'B has twice the e.m.f. of A', 'B', false, 1),
('1fb92600-993e-5276-863b-55d68ce1fd39', '96b2a53e-f29a-5aaa-b2ce-6fd4ba6e8ddf', 'They are equal', 'C', true, 2),
('d0418bfa-8d10-5e8f-bfe7-efbce13f07ea', '96b2a53e-f29a-5aaa-b2ce-6fd4ba6e8ddf', 'B has four times the e.m.f. of A', 'D', false, 3),
('8570bb1e-ee71-5b9b-a117-86670d935e90', '2aa0de82-6fdc-5cfd-829d-e20aa6d3c676', 'Moving the magnet faster gives a larger meter deflection for the same movement', 'A', true, 0),
('c0bffec9-1911-553c-aa4e-818a97244210', '2aa0de82-6fdc-5cfd-829d-e20aa6d3c676', 'Reversing the magnet reverses the deflection', 'B', false, 1),
('0821efed-21ef-529a-a75e-9d610c1146b7', '2aa0de82-6fdc-5cfd-829d-e20aa6d3c676', 'Holding the magnet still gives no deflection', 'C', false, 2),
('ddc7099e-a012-508e-b8f2-800edb10e91d', '2aa0de82-6fdc-5cfd-829d-e20aa6d3c676', 'Adding an iron core changes the deflection', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('481a8bfc-f5e1-5335-ae3d-113e3cafbbd9', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 7, 7, 'Which expression gives the magnetic flux through a flat coil of area A at right angles to a uniform field B?', NULL, 1, 'multiple_choice'::answer_type, 'Φ = BA', NULL, false, NULL, false, NULL, 'Flux is flux density times the area at right angles to the field. Mark scheme (1 mark). B1: C (Φ = BA).', 1),
('72645982-5000-510e-9294-0cb184c4397e', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 8, 8, 'A door-shaped loop of area 2.0 m² is face-on to the Earth''s field of 45 µT. Calculate the flux through it.', NULL, 1, 'numeric'::answer_type, '9e-5', 'Wb', false, NULL, false, NULL, 'Φ = BA = 45 × 10⁻⁶ × 2.0 = 9.0 × 10⁻⁵ Wb. Mark scheme (2 marks). C1: Φ = BA with B in T. A1: Φ = 9.0 × 10⁻⁵ Wb.', 2),
('1a43b75d-c2d6-5a73-a572-b7b643f09409', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 9, 9, 'What is the flux linkage of a coil?', NULL, 1, 'multiple_choice'::answer_type, 'The number of turns multiplied by the flux through each turn, NΦ', NULL, false, NULL, false, NULL, 'Each turn contributes the same flux. Mark scheme (1 mark). B1: A (The number of turns multiplied by the flux through each turn, NΦ).', 1),
('1ad7e857-0767-5f1a-bce5-ad800d0e480d', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 10, 10, 'A 150-turn generator coil has 4.0 × 10⁻⁴ Wb through each turn. Calculate its flux linkage.', NULL, 1, 'numeric'::answer_type, '0.06', 'Wb', false, NULL, false, NULL, 'NΦ = 150 × 4.0 × 10⁻⁴ = 0.060 Wb. Mark scheme (2 marks). C1: NΦ. A1: NΦ = 0.060 Wb.', 2),
('3dce226e-7a3d-550f-b576-92bc2f4de57d', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 11, 11, 'Which statement is Faraday''s law of electromagnetic induction?', NULL, 1, 'multiple_choice'::answer_type, 'The induced e.m.f. is equal to the rate of change of magnetic flux linkage', NULL, false, NULL, false, NULL, 'E = d(NΦ)/dt in magnitude. Mark scheme (1 mark). B1: D (The induced e.m.f. is equal to the rate of change of magnetic flux linkage).', 1),
('81610cc2-46ac-5d35-ac07-04cfbe4b3938', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 12, 12, 'The flux linkage of a coil changes at a steady rate of 0.25 Wb s⁻¹. What e.m.f. is induced?', NULL, 1, 'numeric'::answer_type, '0.25', 'V', false, NULL, false, NULL, 'E = rate of change of flux linkage = 0.25 × 1 = 0.25 V. Mark scheme (2 marks). C1: 1 Wb s⁻¹ = 1 V. A1: E = 0.25 V.', 2),
('4b8afdd9-4757-5707-9e22-6ff035ee7ee8', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 13, 13, 'A metal rod moves at right angles to a magnetic field. Why does one end become negative?', NULL, 1, 'multiple_choice'::answer_type, 'The magnetic force on the free electrons pushes them towards that end', NULL, false, NULL, false, NULL, 'F = Bev acts along the rod on each moving electron. Mark scheme (1 mark). B1: B (The magnetic force on the free electrons pushes them towards that end).', 1),
('58c3dbc9-24c7-574b-8c9f-4064e13dd864', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 14, 14, 'A rod 0.50 m long moves at 3.0 m s⁻¹ across a 0.20 T field. Using E_field = vB inside the rod, calculate the e.m.f. across it.', NULL, 1, 'numeric'::answer_type, '0.3', 'V', false, NULL, false, NULL, 'Electric field in the rod = vB = 3.0 × 0.20 = 0.60 V m⁻¹. e.m.f. = 0.60 × 0.50 = 0.30 V. Mark scheme (2 marks). C1: E_field = vB then × L. A1: E = 0.30 V.', 2),
('0ebcea10-94a2-5dec-8066-91a2e8d494d8', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 15, 15, 'In what sense is "cutting field lines" equivalent to Faraday''s law?', NULL, 1, 'multiple_choice'::answer_type, 'The rate at which a conductor sweeps out flux equals the rate of change of flux linkage', NULL, false, NULL, false, NULL, 'A rod of length L moving at v sweeps out BLv webers per second. Mark scheme (1 mark). B1: C (The rate at which a conductor sweeps out flux equals the rate of change of flux linkage).', 1),
('e3cb633b-7567-5183-bbe2-d412ce0252e7', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 16, 16, 'A 0.40 m rod moving at 2.5 m s⁻¹ at right angles to a 0.15 T field sweeps out an area each second. Calculate the flux it cuts per second, which equals the e.m.f.', NULL, 1, 'numeric'::answer_type, '0.15', 'V', false, NULL, false, NULL, 'Area per second = 0.40 × 2.5 = 1.0 m² s⁻¹. Flux per second = 0.15 × 1.0 = 0.15 Wb s⁻¹, so E = 0.15 V. Mark scheme (2 marks). C1: area swept × B. A1: E = 0.15 V.', 2),
('4468f259-3f29-56ab-8f6b-a34170f0cda1', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 17, 17, 'Which unit is equivalent to the volt?', NULL, 1, 'multiple_choice'::answer_type, 'Wb s⁻¹', NULL, false, NULL, false, NULL, 'E = rate of change of flux linkage. Mark scheme (1 mark). B1: A (Wb s⁻¹).', 1),
('ab333e77-5ae5-513e-965c-814d25bb35b0', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 18, 18, 'A 50-turn coil of area 0.010 m² is in a field of 0.10 T, with its normal at 60° to the field. Calculate its flux linkage.', NULL, 1, 'numeric'::answer_type, '0.025', 'Wb', false, NULL, false, NULL, 'NΦ = NBA cos 60° = 50 × 0.10 × 0.010 × 0.50 = 0.025 Wb. Mark scheme (1 mark). A1: NΦ = 0.025 Wb.', 1),
('9ec33af4-078a-5506-aee5-5824e192e32e', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 19, 19, 'Why does a coil rotating steadily in a uniform field produce an alternating e.m.f.?', NULL, 1, 'multiple_choice'::answer_type, 'Its flux linkage varies sinusoidally, so the rate of change reverses each half turn', NULL, false, NULL, false, NULL, 'NΦ = NBA cos ωt; E = NBAω sin ωt. Mark scheme (1 mark). B1: D (Its flux linkage varies sinusoidally, so the rate of change reverses each half turn).', 1),
('cd6e7059-4e49-5865-b2d9-8bd5815cbe58', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 20, 20, 'A coil of 80 turns and area 0.0050 m² rotates in a field of 0.25 T. Calculate its maximum flux linkage.', NULL, 1, 'numeric'::answer_type, '0.1', 'Wb', false, NULL, false, NULL, 'NΦ_max = NBA = 80 × 0.25 × 0.0050 = 0.10 Wb. Mark scheme (2 marks). C1: NBA. A1: NΦ = 0.10 Wb.', 2),
('f2d16c7f-4d2f-5d2b-82c9-ec57182171f1', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 21, 21, 'At which position of a coil rotating in a uniform field is the induced e.m.f. greatest?', NULL, 1, 'multiple_choice'::answer_type, 'When the plane of the coil is parallel to the field, so the flux linkage is zero but changing fastest', NULL, false, NULL, false, NULL, 'E is the gradient of the NΦ–t graph, largest where NΦ crosses zero. Mark scheme (1 mark). B1: B (When the plane of the coil is parallel to the field, so the flux linkage is zero but changing fastest).', 1),
('b75ec630-0180-5951-8d02-f3d4eff788a6', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 22, 22, 'In half a turn, the flux linkage of a coil changes from +0.10 Wb to −0.10 Wb in 0.010 s. Calculate the average e.m.f.', NULL, 1, 'numeric'::answer_type, '20', 'V', false, NULL, false, NULL, 'Δ(NΦ) = 0.10 − (−0.10) = 0.20 Wb. E = 0.20 ÷ 0.010 = 20 V. Mark scheme (2 marks). C1: change includes sign. A1: E = 20 V.', 2),
('cc947f42-76f7-5328-b0d0-a47cf3939e31', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 23, 23, 'A closed loop moves through a uniform field, staying completely inside it. Why is there no net e.m.f. around the loop?', NULL, 1, 'multiple_choice'::answer_type, 'The flux through the loop does not change', NULL, false, NULL, false, NULL, 'The e.m.f.s in opposite sides are equal and opposite, matching zero change of flux. Mark scheme (1 mark). B1: C (The flux through the loop does not change).', 1),
('7b7565c7-2328-5276-b9e9-e63db04abbb5', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 24, 24, 'A rod moves at 5.0 m s⁻¹ at right angles to a field of 0.40 T. Calculate the magnetic force on each free electron in it, in units of 10⁻¹⁹ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.2', '10⁻¹⁹ N', false, NULL, false, NULL, 'F = Bev = 0.40 × 1.60 × 10⁻¹⁹ × 5.0 = 3.20 × 10⁻¹⁹ N. Mark scheme (3 marks). C1: F = Bev. C1: value. A1: F = 3.2 × 10⁻¹⁹ N.', 3),
('b05d28fb-a9dc-5d4f-8db6-49ed6e67034d', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 25, 25, 'The flux linkage of a coil rises steadily from 0 to 0.050 Wb in 0.020 s. Calculate the induced e.m.f.', NULL, 2, 'numeric'::answer_type, '2.5', 'V', false, NULL, false, NULL, 'E = gradient = 0.050 ÷ 0.020 = 2.5 V. Mark scheme (3 marks). C1: gradient of NΦ–t. C1: value. A1: E = 2.5 V.', 3),
('36fe65e5-459e-5b16-97c5-fe4f61c7eeec', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 26, 26, 'For a coil rotating at constant speed in a uniform field, how is the e.m.f.–time graph related to the flux-linkage–time graph?', NULL, 2, 'multiple_choice'::answer_type, 'The e.m.f. is the (negative) gradient of the flux-linkage graph, so it is a sine curve when flux linkage is a cosine curve', NULL, false, NULL, false, NULL, 'E = −d(NΦ)/dt, so the e.m.f. graph is the gradient of the flux-linkage graph. Mark scheme (3 marks). C1: E = gradient. C1: 90° phase difference. A1: A (The e.m.f. is the (negative) gradient of the flux-linkage graph, so it is a sine curve when flux linkage is a cosine curve).', 3),
('18a51686-d524-5d7a-bf07-0ce2b4cb6105', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 27, 27, 'A coil''s flux linkage falls from its maximum, 0.10 Wb, to zero during a quarter turn. The coil turns at 50 revolutions per second. Calculate the average e.m.f. during this quarter turn.', NULL, 2, 'numeric'::answer_type, '20', 'V', false, NULL, false, NULL, 'Time for a quarter turn = (1/50) ÷ 4 = 5.0 × 10⁻³ s. E = 0.10 ÷ 5.0 × 10⁻³ = 20 V. Mark scheme (4 marks). C1: period. C1: quarter period. C1: average e.m.f. A1: E = 20 V.', 4),
('871f10b4-cb2c-5dc3-9027-90d23d648002', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 28, 28, 'An e.m.f.–time graph for a coil is a triangle with a peak of 0.30 V and a duration of 0.040 s. Calculate the change in flux linkage.', NULL, 2, 'numeric'::answer_type, '0.006', 'Wb', false, NULL, false, NULL, 'Δ(NΦ) = area under graph = 0.5 × 0.30 × 0.040 = 6.0 × 10⁻³ Wb. Mark scheme (3 marks). M1: area = Δ(NΦ). C1: triangle area. A1: Δ(NΦ) = 0.0060 Wb.', 3),
('96100d87-245b-5746-a0a3-0534d7ed2aa9', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 29, 29, 'A coil rotates in a uniform field about an axis parallel to the field. What e.m.f. is induced?', NULL, 2, 'multiple_choice'::answer_type, 'None, because the flux linkage stays constant', NULL, false, NULL, false, NULL, 'The plane of the coil always contains the field direction, so the flux stays zero. Mark scheme (3 marks). C1: flux unchanged. C1: no e.m.f. A1: D (None, because the flux linkage stays constant).', 3),
('0a6617bb-91e2-52d9-9df1-d35bc2c82832', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 30, 30, 'A 40-turn coil of area 2.0 × 10⁻⁴ m² is inside a solenoid where B = 0.050 T, with its plane at right angles to the field. Calculate its flux linkage.', NULL, 2, 'numeric'::answer_type, '4e-4', 'Wb', false, NULL, false, NULL, 'NΦ = 40 × 0.050 × 2.0 × 10⁻⁴ = 4.0 × 10⁻⁴ Wb. Mark scheme (3 marks). C1: Φ = BA. C1: × N. A1: NΦ = 4.0 × 10⁻⁴ Wb.', 3),
('814e3e0b-8cd6-5521-95fa-9e85395796f8', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 31, 31, 'The current in the solenoid in which a coil sits is reversed in 0.10 s, so the coil''s flux linkage goes from +4.0 × 10⁻⁴ Wb to −4.0 × 10⁻⁴ Wb. Calculate the average e.m.f., in mV.', NULL, 2, 'numeric'::answer_type, '8 mV', 'mV', false, NULL, false, NULL, 'Δ(NΦ) = 2 × 4.0 × 10⁻⁴ = 8.0 × 10⁻⁴ Wb. E = 8.0 × 10⁻⁴ ÷ 0.10 = 8.0 × 10⁻³ V. In mV: 8.0 × 10⁻³ × 1000 = 8.0. Mark scheme (4 marks). B1: reversal doubles change. C1: E = Δ(NΦ)/Δt. C1: conversion. A1: E = 8.0 mV.', 4),
('432dfdfd-96a7-5f2f-aa5d-e823d45ecb70', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 32, 32, 'A rod lying north–south moves due east through a magnetic field pointing vertically downwards. Which end of the rod becomes positive?', NULL, 2, 'multiple_choice'::answer_type, 'The north end', NULL, false, NULL, false, NULL, 'The force on the free electrons pushes them to the south end, leaving the north end positive. Mark scheme (3 marks). C1: force on electrons. C1: north end positive. A1: B (The north end).', 3),
('b065657d-db45-5075-ba93-49c69fbb6d49', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 33, 33, 'Find the flux linkage of a 200-turn coil of area 0.0030 m² when a 0.040 T field makes an angle of 50° with its normal.', NULL, 2, 'numeric'::answer_type, '0.01543', 'Wb', false, NULL, false, NULL, 'NΦ = NBA cos θ = 200 × 0.040 × 0.0030 × cos 50° = 0.0154 Wb. Mark scheme (3 marks). C1: NBA cos θ. C1: substitution. A1: NΦ = 0.0154 Wb.', 3),
('86c9b19a-9dcc-5645-9a5d-95fb3510ce19', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 34, 34, 'A rod 1.2 m long moves at 0.50 m s⁻¹ at right angles to a field of 0.80 T. Calculate the induced e.m.f.', NULL, 2, 'numeric'::answer_type, '0.48', 'V', false, NULL, false, NULL, 'E = BLv = 0.80 × 1.2 × 0.50 = 0.48 V. Mark scheme (3 marks). C1: E = BLv. C1: value. A1: E = 0.48 V.', 3),
('2a6eaad8-3630-5d3c-9ed2-42570d9c769f', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 35, 35, 'Why is the unit Wb s⁻¹ equivalent to the volt?', NULL, 2, 'multiple_choice'::answer_type, 'Wb = T m² = (N A⁻¹ m⁻¹)(m²) = N m A⁻¹, and N m A⁻¹ s⁻¹ = J C⁻¹ = V', NULL, false, NULL, false, NULL, 'Work per unit charge: J ÷ (A s) = V. Mark scheme (4 marks). C1: Wb in N m A⁻¹. C1: ÷ s gives J C⁻¹. C1: = V. A1: C (Wb = T m² = (N A⁻¹ m⁻¹)(m²) = N m A⁻¹, and N m A⁻¹ s⁻¹ = J C⁻¹ = V).', 4),
('79a9964b-34c5-5010-87e2-0cb128f38558', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 36, 36, 'A 50-turn coil of area 0.020 m² lies face-on to a field that is increasing at 0.40 T s⁻¹. Calculate the induced e.m.f.', NULL, 2, 'numeric'::answer_type, '0.4', 'V', false, NULL, false, NULL, 'E = NA dB/dt = 50 × 0.020 × 0.40 = 0.40 V. Mark scheme (3 marks). C1: E = NA dB/dt. C1: value. A1: E = 0.40 V.', 3),
('55242ac0-eec0-558c-909f-5a97b13dd353', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 37, 37, 'Calculate the rate of change of flux density needed to induce 1.5 V in a 300-turn coil of area 0.010 m², face-on to the field.', NULL, 2, 'numeric'::answer_type, '0.5', 'T s⁻¹', false, NULL, false, NULL, 'dB/dt = E/(NA) = 1.5 ÷ (300 × 0.010) = 0.50 T s⁻¹. Mark scheme (3 marks). C1: rearranged. C1: value. A1: dB/dt = 0.50 T s⁻¹.', 3),
('27af0daa-3794-5a7a-8099-3f6dd0bab0ee', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 38, 38, 'For a coil rotating in a uniform field, in which position is the flux linkage greatest?', NULL, 2, 'multiple_choice'::answer_type, 'When the plane of the coil is at right angles to the field', NULL, false, NULL, false, NULL, 'NΦ = NBA cos θ is largest when the normal is along the field. Mark scheme (3 marks). C1: normal along B. C1: NBA. A1: A (When the plane of the coil is at right angles to the field).', 3),
('4a084546-9160-5e05-a9f2-691a4b71abc2', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 39, 39, 'A 0.25 m rod moving across a 0.20 T field has an e.m.f. of 0.15 V across it. Using E_field = vB inside the rod, calculate the speed of the rod.', NULL, 2, 'numeric'::answer_type, '3', 'm s⁻¹', false, NULL, false, NULL, 'Electric field in rod = 0.15 ÷ 0.25 = 0.60 V m⁻¹. v = E_field/B = 0.60 ÷ 0.20 = 3.0 m s⁻¹. Mark scheme (4 marks). C1: field = e.m.f./L. M1: eE = Bev. C1: v. A1: v = 3.0 m s⁻¹.', 4),
('d68abe3b-469c-54a9-b31d-3f8edd5e84c0', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 40, 40, 'A 100-turn coil of area 0.010 m² rotates at 100 rad s⁻¹ in a field of 0.20 T. Calculate the peak e.m.f., using E₀ = NBAω.', NULL, 2, 'numeric'::answer_type, '20', 'V', false, NULL, false, NULL, 'E₀ = NBAω = 100 × 0.20 × 0.010 × 100 = 20 V. Mark scheme (3 marks). C1: E₀ = NBAω. C1: value. A1: E₀ = 20 V.', 3),
('503f23a9-3ec2-504f-8bfc-2819bf6909cd', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 41, 41, 'A stationary coil is placed in a magnetic field whose strength is changing. Why is an e.m.f. induced, although nothing moves?', NULL, 2, 'multiple_choice'::answer_type, 'The flux linkage is changing, and Faraday''s law depends only on the rate of change of flux linkage', NULL, false, NULL, false, NULL, 'It does not matter whether the flux changes because of motion or because B changes. Mark scheme (3 marks). C1: changing NΦ. C1: cause irrelevant. A1: D (The flux linkage is changing, and Faraday''s law depends only on the rate of change of flux linkage).', 3),
('2a54d753-f1a9-5979-8681-dbf3b50f9cc3', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 42, 42, '(a) A rod of length L moves at speed v at right angles to a field B. By considering the forces on a free electron when charge stops building up, show that the e.m.f. is BLv. (b) Calculate the e.m.f. for L = 0.30 m, v = 2.0 m s⁻¹ and B = 0.50 T. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.3', 'V', false, NULL, false, NULL, '(a) In equilibrium eE = Bev, so E = vB; the p.d. across the rod is EL = BLv. (b) e.m.f. = 0.50 × 0.30 × 2.0 = 0.30 V. Mark scheme (5 marks). M1: eE = Bev. B1: E = vB. B1: V = EL = BLv. C1: value. A1: E = 0.30 V.', 5),
('c7c586bc-0d21-5c85-b781-f0a08e76eef5', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 43, 43, 'The flux linkage of a coil changes as follows: it rises steadily from 0 to 0.12 Wb between t = 0 and 0.040 s, stays constant until 0.080 s, then falls steadily to zero by 0.10 s. (a) Calculate the e.m.f. during the rise. (b) State the e.m.f. while it is constant. (c) Calculate the size of the e.m.f. during the fall. (d) Explain why the e.m.f.s in (a) and (c) have opposite signs. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '6', 'V', false, NULL, false, NULL, '(a) E = 0.12 ÷ 0.040 = 3.0 V. (b) Zero. (c) E = 0.12 ÷ (0.10 − 0.080) = 6.0 V. (d) The flux linkage increases in one case and decreases in the other, so the gradients have opposite signs. Mark scheme (6 marks). C1: gradient during rise. B1: zero when constant. C1: fall time 0.020 s. C1: value. B1: opposite gradients. A1: E = 6.0 V.', 6),
('797f8772-128e-5232-aa28-82b5c7f02f68', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 44, 44, 'A 50-turn coil of area 0.020 m² rotates at 10 revolutions per second in a field of 0.30 T. (a) Calculate the peak e.m.f., using E₀ = NBA × 2πf. (b) Calculate the average e.m.f. during a quarter turn from maximum flux linkage. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '18.85', 'V', false, NULL, false, NULL, '(a) E₀ = 50 × 0.30 × 0.020 × 2π × 10 = 18.8 V. (b) Δ(NΦ) = 50 × 0.30 × 0.020 = 0.30 Wb in a quarter period of 0.025 s, so E = 0.30 ÷ 0.025 = 12 V. Mark scheme (5 marks). C1: ω = 2πf. C1: E₀ = NBAω. C1: quarter period. C1: average e.m.f. A1: E₀ = 18.8 V.', 5),
('8d384192-2c43-5257-b4d5-8ede06ee45e2', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 45, 45, 'A square coil of 10 turns and side 0.10 m moves at 0.50 m s⁻¹ into a region of uniform field 0.40 T, with its plane at right angles to the field. The region is wider than the coil. (a) Calculate the e.m.f. while the coil is entering. (b) State the e.m.f. once the coil is completely inside. (c) Calculate the maximum flux linkage. (d) Explain why the e.m.f. reverses as the coil leaves. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '0.2', 'V', false, NULL, false, NULL, '(a) E = NBLv = 10 × 0.40 × 0.10 × 0.50 = 0.20 V. (b) Zero, because the flux linkage is constant. (c) NBA = 10 × 0.40 × 0.10² = 0.040 Wb. (d) The flux linkage then decreases, so its rate of change has the opposite sign. Mark scheme (6 marks). C1: E = NBLv. B1: zero inside. C1: NBA. B1: decreasing flux reverses e.m.f. C1: value. A1: E = 0.20 V.', 6),
('c6833525-5e32-5981-93bb-85a0c649fb8c', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 46, 46, 'A 200-turn search coil of area 1.0 × 10⁻⁴ m² is placed face-on in an alternating field B = B₀ sin ωt with B₀ = 0.010 T and frequency 50 Hz. (a) Show that the peak e.m.f. is NAB₀ω. (b) Calculate it. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.06283', 'V', false, NULL, false, NULL, '(a) NΦ = NAB₀ sin ωt, so E = NAB₀ω cos ωt with peak NAB₀ω. (b) E₀ = 200 × 1.0 × 10⁻⁴ × 0.010 × 2π × 50 = 0.0628 V. Mark scheme (5 marks). M1: differentiate NΦ. B1: peak NAB₀ω. C1: ω = 2πf. C1: value. A1: E₀ = 0.0628 V.', 5),
('a79803bc-1848-5371-91b8-d095611f6d6f', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 47, 47, 'A long solenoid with 2000 turns per metre has a 100-turn coil of area 4.0 × 10⁻⁴ m² wound round its middle. The solenoid current rises steadily from 0 to 3.0 A in 0.050 s. (a) Calculate the change in flux density inside the solenoid, using B = µ₀nI. (b) Calculate the change in flux linkage of the coil. (c) Calculate the induced e.m.f., in mV. Give only the answer to (c). Take µ₀ = 4π × 10⁻⁷ H m⁻¹.', NULL, 3, 'numeric'::answer_type, '6.032 mV', 'mV', false, NULL, false, NULL, '(a) ΔB = 4π × 10⁻⁷ × 2000 × 3.0 = 0.00754 T. (b) Δ(NΦ) = 100 × 4.0 × 10⁻⁴ × 0.007540 = 3.02 × 10⁻⁴ Wb. (c) E = 3.016 × 10⁻⁴ ÷ 0.050 = 0.00603 V. In mV: 0.006032 × 1000 = 6.03. Mark scheme (6 marks). C1: ΔB = µ₀nΔI. C1: Δ(NΦ). C1: E = Δ(NΦ)/Δt. C1: conversion. M1: same flux through coil. A1: E = 6.03 mV.', 6),
('64c8d143-73f1-568e-b8d2-23b0714ec261', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 48, 48, 'A rod 0.50 m long carrying an induced current of 2.0 A moves at 3.0 m s⁻¹ across a field of 0.40 T. (a) Calculate the magnetic force on the rod. (b) Explain why this force opposes the motion. (c) Calculate the rate at which work must be done to keep the rod moving. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.2', 'W', false, NULL, false, NULL, '(a) F = BIL = 0.40 × 2.0 × 0.50 = 0.40 N. (b) If it helped the motion, the rod would speed up and gain energy from nowhere. (c) P = Fv = 0.40 × 3.0 = 1.2 W. Mark scheme (5 marks). C1: F = BIL. B1: energy conservation. C1: P = Fv. C1: value. A1: P = 1.2 W.', 5),
('fc2a902a-97ce-575b-8e56-65b237674f76', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 49, 49, 'A 1000-turn coil of area 0.010 m² hangs with its plane vertical, facing north, where the Earth''s horizontal field is 2.0 × 10⁻⁵ T. It is turned through 180° in 0.10 s. (a) Calculate the initial flux linkage. (b) Calculate the change in flux linkage. (c) Calculate the average e.m.f., in mV. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4 mV', 'mV', false, NULL, false, NULL, '(a) NΦ = 1000 × 2.0 × 10⁻⁵ × 0.010 = 2.0 × 10⁻⁴ Wb. (b) It reverses: change = 2 × 2.0 × 10⁻⁴ = 4.0 × 10⁻⁴ Wb. (c) E = 4.0 × 10⁻⁴ ÷ 0.10 = 4.0 × 10⁻³ V. In mV: 4.0 × 10⁻³ × 1000 = 4.0. Mark scheme (5 marks). C1: NBA. B1: reversal doubles change. C1: E. C1: conversion. A1: E = 4.0 mV.', 5),
('4ca9cf29-728d-5c75-9d7a-b03fb9802734', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', 'f7187a6b-c7a4-4e46-9ae9-d6d8824b8ba5', 'a-level', '26.2', '9702 coursebook 26.2 · Explaining electromagnetic induction', 50, 50, 'An e.m.f. pulse from a coil has an area under its e.m.f.–time graph of 3.0 × 10⁻³ V s. (a) State what this area represents. (b) Give the change in flux linkage, in mWb. (c) The coil has 150 turns. Calculate the change in flux through each turn. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3', 'mWb', false, NULL, false, ARRAY['0.003']::text[], '(a) The change in flux linkage, since ∫E dt = Δ(NΦ). (b) 3.0 × 10⁻³ Wb. In mWb: 3.0 × 10⁻³ × 1000 = 3.0. (c) ΔΦ = 3.0 × 10⁻³ ÷ 150 = 2.0 × 10⁻⁵ Wb. Mark scheme (5 marks). B1: area = Δ(NΦ). C1: value in mWb. C1: ÷ N. B1: V s = Wb. A1: Δ(NΦ) = 3.0 mWb.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('74d9a207-3fdd-5819-b40b-246286ec7153', '481a8bfc-f5e1-5335-ae3d-113e3cafbbd9', 'Φ = B/A', 'A', false, 0),
('d18f842b-9b6f-561b-a231-31bfe7d7043c', '481a8bfc-f5e1-5335-ae3d-113e3cafbbd9', 'Φ = A/B', 'B', false, 1),
('a2365d12-32c0-56d0-815d-d772f085d5c3', '481a8bfc-f5e1-5335-ae3d-113e3cafbbd9', 'Φ = BA', 'C', true, 2),
('51b22f2f-f43d-577f-8d9c-2e587cd6e2b4', '481a8bfc-f5e1-5335-ae3d-113e3cafbbd9', 'Φ = BA²', 'D', false, 3),
('e93d7e2f-582b-52b2-bd74-2e5d85616868', '1a43b75d-c2d6-5a73-a572-b7b643f09409', 'The number of turns multiplied by the flux through each turn, NΦ', 'A', true, 0),
('337c7297-83b3-5fbd-a4d3-1ded461441b5', '1a43b75d-c2d6-5a73-a572-b7b643f09409', 'The flux through one turn only', 'B', false, 1),
('a579d312-6a19-503b-8a2a-0201f465757b', '1a43b75d-c2d6-5a73-a572-b7b643f09409', 'The flux divided by the number of turns', 'C', false, 2),
('3faaa965-cfb1-5df7-ae9a-89a6554dce1c', '1a43b75d-c2d6-5a73-a572-b7b643f09409', 'The current multiplied by the number of turns', 'D', false, 3),
('8c09e384-78ac-5524-9046-5334a027f339', '3dce226e-7a3d-550f-b576-92bc2f4de57d', 'The induced e.m.f. is equal to the flux linkage', 'A', false, 0),
('b18cbcec-1d2d-5ce2-9f07-6e33f3982bfe', '3dce226e-7a3d-550f-b576-92bc2f4de57d', 'The induced current opposes the change producing it', 'B', false, 1),
('a1bca391-ba5a-51ee-8889-0af0acb8362c', '3dce226e-7a3d-550f-b576-92bc2f4de57d', 'The induced e.m.f. is equal to the rate of change of current', 'C', false, 2),
('7f961e24-ba22-505f-97f7-98dd623e83a2', '3dce226e-7a3d-550f-b576-92bc2f4de57d', 'The induced e.m.f. is equal to the rate of change of magnetic flux linkage', 'D', true, 3),
('ccc9e16c-755f-5a86-ac8f-0cfd8cd0c548', '4b8afdd9-4757-5707-9e22-6ff035ee7ee8', 'Positive ions leave that end', 'A', false, 0),
('e17c9a02-efdc-59e4-87da-a1528f1a479a', '4b8afdd9-4757-5707-9e22-6ff035ee7ee8', 'The magnetic force on the free electrons pushes them towards that end', 'B', true, 1),
('e14fc7b8-e8a6-52f9-b74b-54ad8139a638', '4b8afdd9-4757-5707-9e22-6ff035ee7ee8', 'The field creates electrons there', 'C', false, 2),
('37559da4-8b8c-5ed4-92f6-ac739afddf21', '4b8afdd9-4757-5707-9e22-6ff035ee7ee8', 'The rod is heated at that end', 'D', false, 3),
('74415e70-a6d7-5f45-857d-fbc10397efb1', '0ebcea10-94a2-5dec-8066-91a2e8d494d8', 'Cutting lines creates new flux', 'A', false, 0),
('5db16aa4-953b-5066-a3e1-022c302a885e', '0ebcea10-94a2-5dec-8066-91a2e8d494d8', 'Only coils can cut field lines', 'B', false, 1),
('fae4cc55-7002-5c80-9317-699fc37a96cb', '0ebcea10-94a2-5dec-8066-91a2e8d494d8', 'The rate at which a conductor sweeps out flux equals the rate of change of flux linkage', 'C', true, 2),
('3e6a260d-75d0-599b-ad65-25cdeb3bbaab', '0ebcea10-94a2-5dec-8066-91a2e8d494d8', 'Cutting lines stops the induced e.m.f.', 'D', false, 3),
('3742a1c9-6796-53ed-996a-fcf9031d007a', '4468f259-3f29-56ab-8f6b-a34170f0cda1', 'Wb s⁻¹', 'A', true, 0),
('1e543fd1-c084-5ac1-9e84-f56aa9781847', '4468f259-3f29-56ab-8f6b-a34170f0cda1', 'Wb s', 'B', false, 1),
('b987bfce-ae8d-5104-af3d-af7e17363ebc', '4468f259-3f29-56ab-8f6b-a34170f0cda1', 'T m⁻²', 'C', false, 2),
('23c4d55c-482c-5fcc-927e-f40c956334e7', '4468f259-3f29-56ab-8f6b-a34170f0cda1', 'Wb A⁻¹', 'D', false, 3),
('8788c09e-db49-547d-a13f-28ea2074108c', '9ec33af4-078a-5506-aee5-5824e192e32e', 'The field reverses each half turn', 'A', false, 0),
('472d427b-abe4-5696-a83d-e531b3fbe444', '9ec33af4-078a-5506-aee5-5824e192e32e', 'The coil''s resistance changes', 'B', false, 1),
('916ac087-29f2-5e1c-9854-73f4c7fdb135', '9ec33af4-078a-5506-aee5-5824e192e32e', 'The coil speeds up and slows down', 'C', false, 2),
('1f1a0d51-2dfa-5ded-aece-d015ae404d28', '9ec33af4-078a-5506-aee5-5824e192e32e', 'Its flux linkage varies sinusoidally, so the rate of change reverses each half turn', 'D', true, 3),
('b725d60f-82a9-5175-aeb5-173a31eefce3', 'f2d16c7f-4d2f-5d2b-82c9-ec57182171f1', 'When the plane is at right angles to the field', 'A', false, 0),
('64413cb1-24fc-566b-b049-c04df0d02065', 'f2d16c7f-4d2f-5d2b-82c9-ec57182171f1', 'When the plane of the coil is parallel to the field, so the flux linkage is zero but changing fastest', 'B', true, 1),
('f55fe00b-5889-56b5-8df8-b3272a3460d3', 'f2d16c7f-4d2f-5d2b-82c9-ec57182171f1', 'When the flux linkage is greatest', 'C', false, 2),
('21535b82-916d-5c94-be30-1ec404655b8e', 'f2d16c7f-4d2f-5d2b-82c9-ec57182171f1', 'The e.m.f. is the same at all positions', 'D', false, 3),
('77f8f528-33fa-5cd3-864c-c31e9dc80b90', 'cc947f42-76f7-5328-b0d0-a47cf3939e31', 'No field lines are cut by any part of the loop', 'A', false, 0),
('30a90f9e-20b1-5dce-9ab1-47492e5373b0', 'cc947f42-76f7-5328-b0d0-a47cf3939e31', 'The loop has no resistance', 'B', false, 1),
('e00a5fa4-b4bd-5138-b84c-576fd801ae57', 'cc947f42-76f7-5328-b0d0-a47cf3939e31', 'The flux through the loop does not change', 'C', true, 2),
('3498428a-c555-50a4-9d85-63a753c3e1b1', 'cc947f42-76f7-5328-b0d0-a47cf3939e31', 'The e.m.f. is cancelled by the field', 'D', false, 3),
('9fb251a4-bf11-57f9-b869-30f5dbd5a537', '36fe65e5-459e-5b16-97c5-fe4f61c7eeec', 'The e.m.f. is the (negative) gradient of the flux-linkage graph, so it is a sine curve when flux linkage is a cosine curve', 'A', true, 0),
('8b4e7b2a-5498-500c-ad62-c7afb6472a4e', '36fe65e5-459e-5b16-97c5-fe4f61c7eeec', 'They are identical', 'B', false, 1),
('fb08e112-4b81-5e28-a07d-1da5fdee3686', '36fe65e5-459e-5b16-97c5-fe4f61c7eeec', 'The e.m.f. is the area under the flux-linkage graph', 'C', false, 2),
('02465e3b-50b2-5511-8ddf-c7484517279c', '36fe65e5-459e-5b16-97c5-fe4f61c7eeec', 'The e.m.f. is constant', 'D', false, 3),
('e381f81f-abd0-559b-acef-dbbf914a9d29', '96100d87-245b-5746-a0a3-0534d7ed2aa9', 'An alternating e.m.f.', 'A', false, 0),
('b1eeb005-5316-5df6-929a-46c4de85bc92', '96100d87-245b-5746-a0a3-0534d7ed2aa9', 'A steady e.m.f.', 'B', false, 1),
('4f2e706b-1fac-5f20-99c1-af60cd7fc625', '96100d87-245b-5746-a0a3-0534d7ed2aa9', 'An e.m.f. that doubles each turn', 'C', false, 2),
('91f7e198-be2e-55c9-b978-f31855ca487b', '96100d87-245b-5746-a0a3-0534d7ed2aa9', 'None, because the flux linkage stays constant', 'D', true, 3),
('6bfe0490-a963-5946-a2e2-2e250cb15e31', '432dfdfd-96a7-5f2f-aa5d-e823d45ecb70', 'The south end', 'A', false, 0),
('46c6d6e5-97f5-556f-82cb-1013bd703dc6', '432dfdfd-96a7-5f2f-aa5d-e823d45ecb70', 'The north end', 'B', true, 1),
('bf9982d6-d69c-5351-9adb-73cab7be83b0', '432dfdfd-96a7-5f2f-aa5d-e823d45ecb70', 'Neither: no e.m.f. is induced', 'C', false, 2),
('a2bf659a-a2ee-5549-af55-4fc0476eb3f4', '432dfdfd-96a7-5f2f-aa5d-e823d45ecb70', 'Both ends equally', 'D', false, 3),
('fb459144-31fa-564a-af11-cde71f68c91e', '2a6eaad8-3630-5d3c-9ed2-42570d9c769f', 'Wb = V, so Wb s⁻¹ = V s⁻¹', 'A', false, 0),
('c216dc76-99be-5cae-a71b-2be9d9672424', '2a6eaad8-3630-5d3c-9ed2-42570d9c769f', 'Because e.m.f. is measured in webers', 'B', false, 1),
('69ee746d-e18a-5a53-ae3f-9e9d6830209e', '2a6eaad8-3630-5d3c-9ed2-42570d9c769f', 'Wb = T m² = (N A⁻¹ m⁻¹)(m²) = N m A⁻¹, and N m A⁻¹ s⁻¹ = J C⁻¹ = V', 'C', true, 2),
('074d18d0-81e0-53cf-9e44-e110f7b95d74', '2a6eaad8-3630-5d3c-9ed2-42570d9c769f', 'Wb s⁻¹ = A, which equals V', 'D', false, 3),
('0164058f-7305-5149-aff5-2e6a5899b18e', '27af0daa-3794-5a7a-8099-3f6dd0bab0ee', 'When the plane of the coil is at right angles to the field', 'A', true, 0),
('488219d2-8811-5b5d-9312-57c1d5187ee7', '27af0daa-3794-5a7a-8099-3f6dd0bab0ee', 'When the plane of the coil is parallel to the field', 'B', false, 1),
('d6001b2c-52e1-5401-9671-7f5acea185aa', '27af0daa-3794-5a7a-8099-3f6dd0bab0ee', 'At 45°', 'C', false, 2),
('a99be559-a77e-59fd-8682-460ca945c970', '27af0daa-3794-5a7a-8099-3f6dd0bab0ee', 'It is the same at all positions', 'D', false, 3),
('d4b67d0c-c82b-5f02-bc45-b1b213d4efff', '503f23a9-3ec2-504f-8bfc-2819bf6909cd', 'A moving field always contains moving charges', 'A', false, 0),
('45fc517c-6088-548f-8688-0515e3af3ec4', '503f23a9-3ec2-504f-8bfc-2819bf6909cd', 'The coil becomes magnetised', 'B', false, 1),
('88ea2612-fa23-5fa9-8b60-b284f6243b73', '503f23a9-3ec2-504f-8bfc-2819bf6909cd', 'The changing field heats the coil', 'C', false, 2),
('4d039d39-d22a-568e-aca8-03909544f1a4', '503f23a9-3ec2-504f-8bfc-2819bf6909cd', 'The flux linkage is changing, and Faraday''s law depends only on the rate of change of flux linkage', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('bb8b9b54-8bf7-51a1-8344-ae6d46bc99be', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 9, 9, 'The flux through each turn of a 250-turn coil changes by 1.6 × 10⁻⁴ Wb in 0.040 s. Calculate the average e.m.f.', NULL, 1, 'numeric'::answer_type, '1', 'V', false, NULL, false, NULL, 'E = NΔΦ/Δt = 250 × 1.6 × 10⁻⁴ ÷ 0.040 = 1.0 V. Mark scheme (2 marks). C1: E = NΔΦ/Δt. A1: E = 1.0 V.', 2),
('01ff24de-fa6f-52c1-8db6-033ecc84109b', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 10, 10, 'A 60-turn coil of area 0.0050 m² is face-on to a field that rises from 0 to 0.40 T in 0.20 s. Calculate the average e.m.f.', NULL, 1, 'numeric'::answer_type, '0.6', 'V', false, NULL, false, NULL, 'E = NAΔB/Δt = 60 × 0.0050 × 0.40 ÷ 0.20 = 0.60 V. Mark scheme (2 marks). C1: E = NAΔB/Δt. A1: E = 0.60 V.', 2),
('a6e786fc-100c-51fb-9d74-b38d4d38a749', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 11, 11, 'In Faraday''s law written as E = −d(NΦ)/dt, what does the minus sign represent?', NULL, 1, 'multiple_choice'::answer_type, 'Lenz''s law: the induced e.m.f. opposes the change producing it', NULL, false, NULL, false, NULL, 'The sign shows the direction of the induced e.m.f. Mark scheme (1 mark). B1: C (Lenz''s law: the induced e.m.f. opposes the change producing it).', 1),
('9580d573-798b-591d-833f-154fdd0e7f4c', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 12, 12, 'A flux linkage change of 0.050 Wb produces an average e.m.f. of 2.5 V. How long did the change take?', NULL, 1, 'numeric'::answer_type, '0.02', 's', false, NULL, false, NULL, 'Δt = Δ(NΦ)/E = 0.050 ÷ 2.5 = 0.020 s. Mark scheme (2 marks). C1: rearranged. A1: Δt = 0.020 s.', 2),
('6a1c0ff2-0652-5ea8-b664-4719d1ebb468', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 13, 13, 'A coil sits in a strong, constant magnetic field. What e.m.f. is induced?', NULL, 1, 'multiple_choice'::answer_type, 'None, because the flux linkage is not changing', NULL, false, NULL, false, NULL, 'Only a change of flux linkage induces an e.m.f. Mark scheme (1 mark). B1: A (None, because the flux linkage is not changing).', 1),
('7db6b409-00e0-525b-9d2d-756fd1121452', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 14, 14, 'A 0.15 m conductor on a wheel moves at 12 m s⁻¹ at right angles to a 0.25 T field. Calculate the e.m.f. induced across it.', NULL, 1, 'numeric'::answer_type, '0.45', 'V', false, NULL, false, NULL, 'E = BLv = 0.25 × 0.15 × 12 = 0.45 V. Mark scheme (2 marks). C1: E = BLv. A1: E = 0.45 V.', 2),
('b0cd62be-c33d-5624-91be-03367e91d865', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 15, 15, 'From which graph can the induced e.m.f. in a coil be found as the gradient?', NULL, 1, 'multiple_choice'::answer_type, 'Flux linkage against time', NULL, false, NULL, false, NULL, 'E = d(NΦ)/dt, the gradient of the flux linkage against time graph. Mark scheme (1 mark). B1: D (Flux linkage against time).', 1),
('9e727b0e-a96d-57e3-b120-36a28f793b50', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 16, 16, 'A single loop of area 0.030 m² is face-on to a field increasing at 0.50 T s⁻¹. Calculate the induced e.m.f.', NULL, 1, 'numeric'::answer_type, '0.015', 'V', false, NULL, false, NULL, 'E = A dB/dt = 0.030 × 0.50 = 0.015 V. Mark scheme (2 marks). C1: E = A dB/dt. A1: E = 0.015 V.', 2),
('f09e5a82-2bae-54a1-b65f-e893a2e49b4f', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 17, 17, 'The rate of change of flux linkage in a coil is doubled. What happens to the induced e.m.f.?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'E is equal to the rate of change of flux linkage. Mark scheme (1 mark). B1: B (It doubles).', 1),
('2c4999e9-d84e-55a3-a9d0-977f620436d4', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 18, 18, 'An average e.m.f. of 0.30 V is induced in a coil for 0.50 s. Calculate the change in flux linkage.', NULL, 1, 'numeric'::answer_type, '0.15', 'Wb', false, NULL, false, NULL, 'Δ(NΦ) = E × Δt = 0.30 × 0.50 = 0.15 Wb. Mark scheme (2 marks). C1: Δ(NΦ) = EΔt. A1: Δ(NΦ) = 0.15 Wb.', 2),
('c83c4051-f6f5-5eb9-9dc2-07e8a7b0c852', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 19, 19, 'What does the size of the induced e.m.f. in a coil depend on?', NULL, 1, 'multiple_choice'::answer_type, 'The rate at which the flux linkage changes', NULL, false, NULL, false, NULL, 'A large but constant flux gives no e.m.f. Mark scheme (1 mark). B1: C (The rate at which the flux linkage changes).', 1),
('c1e7dbc6-d90a-5c9d-b204-57f5a86e4689', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 20, 20, 'Ten turns of wire enclose an area of 0.020 m². The field through them is switched from +0.30 T to −0.30 T in 0.10 s. Find the average e.m.f.', NULL, 1, 'numeric'::answer_type, '1.2', 'V', false, NULL, false, NULL, 'ΔB = 0.30 − (−0.30) = 0.60 T. E = NAΔB/Δt = 10 × 0.020 × 0.60 ÷ 0.10 = 1.2 V. Mark scheme (2 marks). C1: ΔB includes reversal. A1: E = 1.2 V.', 2),
('c17c3a27-8232-5f3c-a1d9-2c997e4d240a', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 21, 21, 'The same change of flux linkage happens in four different times. When is the induced e.m.f. largest?', NULL, 1, 'multiple_choice'::answer_type, 'When the change happens in the shortest time', NULL, false, NULL, false, NULL, 'E = Δ(NΦ)/Δt, so for the same change the shortest time gives the largest e.m.f. Mark scheme (1 mark). B1: A (When the change happens in the shortest time).', 1),
('8542382f-6c4c-5de8-9bdd-54d68782ee80', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 22, 22, 'A flux change induces an average e.m.f. of 0.80 V. The same change is made in twice the time. What is the new average e.m.f.?', NULL, 1, 'numeric'::answer_type, '0.4', 'V', false, NULL, false, NULL, 'E ∝ 1/Δt: 0.80 ÷ 2 = 0.40 V. Mark scheme (1 mark). A1: E = 0.40 V.', 1),
('7c86a8e9-7e13-50cb-9c29-1cb56f0c5d49', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 23, 23, 'How is the e.m.f. E = BLv for a moving rod related to Faraday''s law?', NULL, 1, 'multiple_choice'::answer_type, 'It is Faraday''s law applied to the flux the rod sweeps out per second, BLv', NULL, false, NULL, false, NULL, 'Flux swept per second = B × (L × v). Mark scheme (1 mark). B1: D (It is Faraday''s law applied to the flux the rod sweeps out per second, BLv).', 1),
('508f3157-88c7-5dda-8c0d-69b6cd2861ca', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 24, 24, 'A magnet is pulled out of an 80-turn coil, and the flux through each turn falls from 5.0 × 10⁻⁵ Wb to zero in 0.025 s. Calculate the average e.m.f.', NULL, 1, 'numeric'::answer_type, '0.16', 'V', false, NULL, false, NULL, 'E = NΔΦ/Δt = 80 × 5.0 × 10⁻⁵ ÷ 0.025 = 0.16 V. Mark scheme (2 marks). C1: E = NΔΦ/Δt. A1: E = 0.16 V.', 2),
('99759623-478f-5a7d-84f6-ff4da7c23a96', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 25, 25, 'A changing magnetic field passes through a coil whose ends are not connected. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'An e.m.f. is induced across the ends but no current flows', NULL, false, NULL, false, NULL, 'Faraday''s law gives the e.m.f.; a current needs a closed circuit. Mark scheme (1 mark). B1: B (An e.m.f. is induced across the ends but no current flows).', 1),
('69389df9-9075-5822-9917-9d639d50cff7', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 26, 26, 'A graph of flux linkage against time for a coil is a straight line from 0.020 Wb at t = 0 to 0.080 Wb at t = 0.050 s. Calculate the induced e.m.f.', NULL, 2, 'numeric'::answer_type, '1.2', 'V', false, NULL, false, NULL, 'E = gradient = (0.080 − 0.020) ÷ 0.050 = 1.2 V. Mark scheme (3 marks). C1: gradient of NΦ–t. C1: value. A1: E = 1.2 V.', 3),
('d4c954d1-59eb-5372-b1b9-a904143c5f8b', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 27, 27, 'A 50-turn coil in a constant field of 0.20 T is squashed so that its area falls from 0.010 m² to 0.0040 m² in 0.30 s. Calculate the average e.m.f.', NULL, 2, 'numeric'::answer_type, '0.2', 'V', false, NULL, false, NULL, 'Δ(NΦ) = NBΔA = 50 × 0.20 × (0.010 − 0.0040) = 0.060 Wb. E = 0.060 ÷ 0.30 = 0.20 V. Mark scheme (3 marks). C1: ΔA. C1: E = NBΔA/Δt. A1: E = 0.20 V.', 3),
('c90cf474-efbf-5da6-886b-ca273b3475af', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 28, 28, 'The flux density through a coil increases at a steady rate. Which describes the graph of induced e.m.f. against time?', NULL, 2, 'multiple_choice'::answer_type, 'A horizontal line: the e.m.f. is constant', NULL, false, NULL, false, NULL, 'A constant rate of change of flux gives a constant e.m.f. Mark scheme (3 marks). C1: constant dΦ/dt. C1: constant E. A1: C (A horizontal line: the e.m.f. is constant).', 3),
('5a2889f0-08f8-50cc-8e37-311b52dd9448', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 29, 29, 'The field inside a solenoid falls steadily from 0.12 T to zero in 0.060 s. A 150-turn coil of radius 1.0 cm is wound round the solenoid. Calculate the average e.m.f., in mV.', NULL, 2, 'numeric'::answer_type, '94.25 mV', 'mV', false, NULL, false, NULL, 'A = π × 0.010² = 3.14 × 10⁻⁴ m². E = NAΔB/Δt = 150 × 3.142 × 10⁻⁴ × 0.12 ÷ 0.060 = 0.0942 V. In mV: 0.09425 × 1000 = 94.2. Mark scheme (4 marks). C1: area. C1: E = NAΔB/Δt. C1: conversion. A1: E = 94.2 mV.', 4),
('2cd76ae0-ba1c-527f-9755-06e9e77059b4', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 30, 30, 'A 0.10 m rod moves at 2.0 m s⁻¹ along rails across a 0.50 T field. The total circuit resistance is 0.20 Ω. Calculate the current.', NULL, 2, 'numeric'::answer_type, '0.5', 'A', false, NULL, false, NULL, 'E = BLv = 0.50 × 0.10 × 2.0 = 0.10 V. I = 0.10 ÷ 0.20 = 0.50 A. Mark scheme (3 marks). C1: E = BLv. C1: I = E/R. A1: I = 0.50 A.', 3),
('82846f8f-197b-5723-bc25-98274d248651', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 31, 31, 'The number of turns on a coil is doubled and the same change of flux per turn takes half as long. By what factor does the e.m.f. change?', NULL, 2, 'multiple_choice'::answer_type, '4', NULL, false, NULL, false, NULL, 'E = NΔΦ/Δt: 2 ÷ ½ = 4. Mark scheme (3 marks). C1: E ∝ N/Δt. C1: factor 4. A1: A (4).', 3),
('199dcc07-23e8-52d9-b84f-2dfafda4497e', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 32, 32, 'A 300-turn coil of area 4.0 × 10⁻³ m² is turned from face-on to edge-on in a field of 0.050 T in 0.025 s. Calculate the average e.m.f.', NULL, 2, 'numeric'::answer_type, '2.4', 'V', false, NULL, false, NULL, 'Δ(NΦ) = NBA = 300 × 0.050 × 4.0 × 10⁻³ = 0.060 Wb. E = 0.060 ÷ 0.025 = 2.4 V. Mark scheme (3 marks). C1: flux linkage change. C1: E. A1: E = 2.4 V.', 3),
('cea34103-6400-56c0-a3a2-5471b6dd50bf', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 33, 33, 'A 0.30 m rod moves across a 0.40 T field and must produce an average e.m.f. of 0.24 V while it moves 0.50 m. How long should the movement take?', NULL, 2, 'numeric'::answer_type, '0.25', 's', false, NULL, false, NULL, 'Flux swept = BLd = 0.40 × 0.30 × 0.50 = 0.060 Wb. t = 0.060 ÷ 0.24 = 0.25 s. Mark scheme (4 marks). C1: flux swept. M1: E = flux/t. C1: t. A1: t = 0.25 s.', 4),
('95757054-069c-50a7-9e38-3c78d2b002b9', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 34, 34, 'Which equation expresses Faraday''s and Lenz''s laws together?', NULL, 2, 'multiple_choice'::answer_type, 'E = −d(NΦ)/dt', NULL, false, NULL, false, NULL, 'The magnitude is the rate of change of flux linkage; the sign gives the opposing direction. Mark scheme (3 marks). C1: rate of change. C1: minus sign. A1: D (E = −d(NΦ)/dt).', 3),
('f5e4659d-c722-5bb4-98ce-8c417b8ad379', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 35, 35, 'A 400-turn coil has an induced e.m.f. of 1.2 V. Calculate the rate of change of flux through each turn.', NULL, 2, 'numeric'::answer_type, '0.003', 'Wb s⁻¹', false, NULL, false, NULL, 'dΦ/dt = E/N = 1.2 ÷ 400 = 3.0 × 10⁻³ Wb s⁻¹. Mark scheme (3 marks). C1: E = N dΦ/dt. C1: value. A1: dΦ/dt = 0.0030 Wb s⁻¹.', 3),
('850d00be-f678-53b9-b252-6d1f45e9c3e7', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 36, 36, 'A 500-turn coil of area 2.0 × 10⁻³ m² faces a changing field and has an e.m.f. of 2.0 V. Calculate the rate of change of the flux density.', NULL, 2, 'numeric'::answer_type, '2', 'T s⁻¹', false, NULL, false, NULL, 'dB/dt = E/(NA) = 2.0 ÷ (500 × 2.0 × 10⁻³) = 2.0 T s⁻¹. Mark scheme (3 marks). C1: rearranged. C1: value. A1: dB/dt = 2.0 T s⁻¹.', 3),
('7d3d1acf-d0b7-5614-93e7-fa18d7735c13', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 37, 37, 'A coil is pulled out of a magnetic field, first slowly and then quickly. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The quick pull gives a larger e.m.f. for a shorter time; the total change of flux linkage is the same', NULL, false, NULL, false, NULL, 'The same Δ(NΦ) over a shorter Δt gives a larger E. Mark scheme (4 marks). C1: same Δ(NΦ). C1: E ∝ 1/Δt. C1: area under E–t same. A1: B (The quick pull gives a larger e.m.f. for a shorter time; the total change of flux linkage is the same).', 4),
('9bd50b7b-a131-5add-9e04-13349c0d47b3', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 38, 38, 'A flux linkage change of 0.030 Wb takes place in 0.050 s in a coil connected to a total resistance of 4.0 Ω. Calculate the average current.', NULL, 2, 'numeric'::answer_type, '0.15', 'A', false, NULL, false, NULL, 'E = 0.030 ÷ 0.050 = 0.60 V. I = 0.60 ÷ 4.0 = 0.15 A. Mark scheme (3 marks). C1: average e.m.f. C1: I = E/R. A1: I = 0.15 A.', 3),
('f529c4a9-b558-5bed-a292-a5564e694aa1', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 39, 39, 'A coil of total resistance 4.0 Ω has its flux linkage changed by 0.030 Wb. Calculate the charge that flows, in mC.', NULL, 2, 'numeric'::answer_type, '7.5 mC', 'mC', false, NULL, false, NULL, 'Q = Δ(NΦ)/R = 0.030 ÷ 4.0 = 7.5 × 10⁻³ C. In mC: 7.5 × 10⁻³ × 1000 = 7.5. Mark scheme (4 marks). M1: Q = It = (E/R)t. C1: Q = Δ(NΦ)/R. C1: conversion. A1: Q = 7.5 mC.', 4),
('48fa0dbc-a5f8-55d9-819a-fedbd87dac33', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 40, 40, 'The flux linkage of a rotating coil varies as a sine curve. At which points is the induced e.m.f. greatest?', NULL, 2, 'multiple_choice'::answer_type, 'Where the flux linkage is zero', NULL, false, NULL, false, NULL, 'The gradient of a sine curve is greatest where it crosses zero. Mark scheme (3 marks). C1: E = gradient. C1: steepest at zero. A1: C (Where the flux linkage is zero).', 3),
('12cada2a-ca9d-5a7f-9645-b36674d4ba5f', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 41, 41, 'A 200-turn coil of area 2.0 × 10⁻³ m² is face-on to a field that rises steadily from 0 to 0.50 T in 0.20 s, stays constant for 0.30 s, then falls steadily to zero in 0.10 s. (a) Calculate the e.m.f. during the rise. (b) State the e.m.f. while the field is constant. (c) Calculate the size of the e.m.f. during the fall. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2', 'V', false, NULL, false, NULL, '(a) E = 200 × 2.0 × 10⁻³ × 0.50 ÷ 0.20 = 1.0 V. (b) Zero. (c) E = 200 × 2.0 × 10⁻³ × 0.50 ÷ 0.10 = 2.0 V, in the opposite direction. Mark scheme (6 marks). C1: rise e.m.f. B1: zero when constant. C1: fall e.m.f. B1: opposite sign. M1: E = NA dB/dt. A1: E = 2.0 V.', 6),
('fac2f624-ddaa-5ca2-a854-04495fb5d32b', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 42, 42, 'A generator coil of 500 turns and area 0.010 m² turns at 3000 revolutions per minute in a field of 0.15 T. (a) Calculate its angular speed. (b) Calculate the peak e.m.f., using E₀ = NBAω. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '235.6', 'V', false, NULL, false, NULL, '(a) ω = 3000 × 2π ÷ 60 = 314 rad s⁻¹. (b) E₀ = 500 × 0.15 × 0.010 × 314.2 = 236 V. Mark scheme (5 marks). C1: rev min⁻¹ to rad s⁻¹. C1: E₀ = NBAω. C1: substitution. C1: value. A1: E₀ = 236 V.', 5),
('9764fff4-7376-5d71-b7ba-dd6b19124689', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 43, 43, 'A rod 0.20 m long rests on horizontal rails joined by a 0.40 Ω resistor, at right angles to a vertical field of 0.50 T. A constant horizontal force of 0.10 N pulls the rod. (a) Show that the opposing magnetic force at speed v is B²L²v/R. (b) Explain why the rod reaches a terminal speed. (c) Calculate the terminal speed. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4', 'm s⁻¹', false, NULL, false, NULL, '(a) E = BLv, I = BLv/R, F = BIL = B²L²v/R. (b) The opposing force grows with speed until it equals 0.10 N. (c) v = FR/(B²L²) = 0.10 × 0.40 ÷ (0.50² × 0.20²) = 4.0 m s⁻¹. Mark scheme (6 marks). M1: chain E → I → F. B1: B²L²v/R. B1: force grows with speed. C1: rearranged. C1: value. A1: v = 4.0 m s⁻¹.', 6),
('a22ff4ed-4030-51e3-ace9-d3ac35eb4a28', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 44, 44, 'A 50-turn search coil of area 2.0 × 10⁻⁴ m², connected to a circuit of total resistance 25 Ω, is pulled quickly out of a magnetic field. A charge of 1.2 × 10⁻⁴ C flows. (a) Calculate the change in flux linkage. (b) Calculate the flux density. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.3', 'T', false, NULL, false, NULL, '(a) Δ(NΦ) = QR = 1.2 × 10⁻⁴ × 25 = 3.0 × 10⁻³ Wb. (b) B = Δ(NΦ)/(NA) = 3.0 × 10⁻³ ÷ (50 × 2.0 × 10⁻⁴) = 0.30 T. Mark scheme (5 marks). M1: Q = Δ(NΦ)/R. C1: Δ(NΦ). C1: B = Δ(NΦ)/(NA). C1: value. A1: B = 0.30 T.', 5),
('e59a5b2f-6015-57ea-819c-8f00226267c6', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 45, 45, 'A 100-turn coil of area 0.0050 m² rotates in a uniform field. The peak e.m.f. is measured at different frequencies: f/Hz = 5.0, 10, 15, 20 and E₀/V = 1.6, 3.1, 4.7, 6.3. (a) Show that E₀ is proportional to f. (b) Calculate the gradient of the E₀–f graph using the first and last points. (c) Use E₀ = NBA × 2πf to find B. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.09974', 'T', false, NULL, false, NULL, '(a) E₀/f ≈ 0.31 V Hz⁻¹ for every reading. (b) Gradient = (6.3 − 1.6) ÷ (20 − 5.0) = 0.313 V s. (c) B = gradient ÷ (2πNA) = 0.3133 ÷ (2π × 100 × 0.0050) = 0.0997 T. Mark scheme (6 marks). B1: E₀/f constant. C1: gradient. M1: gradient = 2πNBA. C1: rearranged. C1: value. A1: B = 0.0997 T.', 6),
('32177712-3d75-505c-b579-6cf598a5f6fd', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 46, 46, 'A long solenoid with 1000 turns per metre carries a current I = 2.0 + 5.0t (in A, with t in s). A 50-turn coil of area 3.0 × 10⁻⁴ m² is wound round it. (a) Calculate the rate of change of the field inside, using B = µ₀nI. (b) Calculate the e.m.f. induced in the coil, in µV. Give only the answer to (b). Take µ₀ = 4π × 10⁻⁷ H m⁻¹.', NULL, 3, 'numeric'::answer_type, '94.25 uV', 'µV', false, NULL, false, NULL, '(a) dB/dt = µ₀n dI/dt = 4π × 10⁻⁷ × 1000 × 5.0 = 0.00628 T s⁻¹. (b) E = NA dB/dt = 50 × 3.0 × 10⁻⁴ × 0.006283 = 9.42 × 10⁻⁵ V. In µV: 9.425 × 10⁻⁵ × 10⁶ = 94.2. Mark scheme (5 marks). C1: dI/dt = 5.0 A s⁻¹. C1: dB/dt. C1: E = NA dB/dt. C1: conversion. A1: E = 94.2 µV.', 5),
('8934cc1f-453f-5879-b3d9-33157f2b0796', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 47, 47, 'A rod with resistance 0.50 Ω moves at 3.0 m s⁻¹ along rails across a 0.40 T field. The rod is 0.50 m long and the rails are joined by a 1.5 Ω resistor. (a) Calculate the e.m.f. (b) Calculate the current. (c) Calculate the p.d. across the 1.5 Ω resistor. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.45', 'V', false, NULL, false, NULL, '(a) E = 0.40 × 0.50 × 3.0 = 0.60 V. (b) I = 0.60 ÷ (1.5 + 0.50) = 0.30 A. (c) V = IR = 0.30 × 1.5 = 0.45 V: less than the e.m.f. because of the rod''s internal resistance. Mark scheme (6 marks). C1: E = BLv. M1: rod acts as source with internal resistance. C1: I. C1: V = IR. B1: lost volts in rod. A1: V = 0.45 V.', 6),
('2728f79f-51f5-59f0-9f72-d6f04aafd1d3', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 48, 48, 'For a sinusoidal supply, the r.m.s. voltage across a transformer''s primary coil is related to the peak flux Φ₀ in its core by V = 4.44fNΦ₀. A primary coil of 1000 turns is connected to 230 V at 50 Hz. (a) Calculate the peak flux in the core, in mWb. (b) Explain why the core needs to be made of a magnetic material. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '1.036', 'mWb', false, NULL, false, ARRAY['0.001036']::text[], '(a) Φ₀ = 230 ÷ (4.44 × 50 × 1000) = 0.00104 Wb. In mWb: 0.001036 × 1000 = 1.04. (b) Iron concentrates the flux, so a large flux links both coils with a small magnetising current. Mark scheme (5 marks). C1: rearranged. C1: substitution. C1: conversion. B1: core concentrates and links flux. A1: Φ₀ = 1.04 mWb.', 5),
('e75b5b14-c01a-5c47-9999-60edf8963617', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 49, 49, 'A circular loop of wire lies face-on to a field of 0.50 T. Its radius is decreasing at 0.020 m s⁻¹, and is 0.10 m at the instant considered. (a) Show that the rate of change of area is 2πr dr/dt. (b) Calculate the induced e.m.f. at this instant, in mV. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '6.283 mV', 'mV', false, NULL, false, NULL, '(a) A = πr², so dA/dt = 2πr dr/dt. (b) E = B dA/dt = 0.50 × 2π × 0.10 × 0.020 = 0.00628 V. In mV: 0.006283 × 1000 = 6.28. Mark scheme (6 marks). M1: differentiate A = πr². B1: 2πr dr/dt. C1: E = B dA/dt. C1: substitution. C1: conversion. A1: E = 6.28 mV.', 6),
('861da3ac-4c7b-5603-9228-99c25aa5bed4', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '2ad404cd-23bd-5405-96a2-9ca0a634169b', 'a-level', '26.3', '9702 coursebook 26.3 · Electromagnetic induction', 50, 50, 'A 2000-turn coil of area 0.020 m² lies flat on a bench where the vertical component of the Earth''s field is 4.5 × 10⁻⁵ T. It is flipped over in 0.10 s. (a) Calculate the change in flux linkage. (b) Calculate the average e.m.f., in mV. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '36 mV', 'mV', false, NULL, false, NULL, '(a) Δ(NΦ) = 2NBA = 2 × 2000 × 4.5 × 10⁻⁵ × 0.020 = 3.6 × 10⁻³ Wb. (b) E = 3.6 × 10⁻³ ÷ 0.10 = 0.036 V. In mV: 0.036 × 1000 = 36. Mark scheme (5 marks). B1: flipping doubles change. C1: Δ(NΦ). C1: E. C1: conversion. A1: E = 36 mV.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('064e27e9-17bb-5c92-9dbb-1685c3b05a80', 'a6e786fc-100c-51fb-9d74-b38d4d38a749', 'That the e.m.f. is always negative', 'A', false, 0),
('3155cca7-c485-5825-aae5-27c1b91c07c9', 'a6e786fc-100c-51fb-9d74-b38d4d38a749', 'That flux is a vector', 'B', false, 1),
('c4b89b42-e220-5cff-bf00-cb1aeaaaae43', 'a6e786fc-100c-51fb-9d74-b38d4d38a749', 'Lenz''s law: the induced e.m.f. opposes the change producing it', 'C', true, 2),
('4455dfc8-7843-51ab-9a69-fd14c0d4a7a4', 'a6e786fc-100c-51fb-9d74-b38d4d38a749', 'That energy is lost as heat', 'D', false, 3),
('addacfb3-6c6c-560e-9f2a-237cb0973d64', '6a1c0ff2-0652-5ea8-b664-4719d1ebb468', 'None, because the flux linkage is not changing', 'A', true, 0),
('b66fa2cd-1f31-5672-a41a-f3a07ad1c9be', '6a1c0ff2-0652-5ea8-b664-4719d1ebb468', 'A large e.m.f., because the field is strong', 'B', false, 1),
('8c318cd9-c4cb-5156-8abf-fca3c2c34767', '6a1c0ff2-0652-5ea8-b664-4719d1ebb468', 'A small alternating e.m.f.', 'C', false, 2),
('8b5d45c9-b2bd-5411-9c13-ae27cd4c0678', '6a1c0ff2-0652-5ea8-b664-4719d1ebb468', 'An e.m.f. equal to NBA', 'D', false, 3),
('9c4c3729-5983-5b67-a453-252444e91a79', 'b0cd62be-c33d-5624-91be-03367e91d865', 'Flux linkage against current', 'A', false, 0),
('3660b839-7d18-5928-b037-d10ca0006e07', 'b0cd62be-c33d-5624-91be-03367e91d865', 'Current against time', 'B', false, 1),
('5ab8904b-1c94-5bea-bf43-676ec9cfaee8', 'b0cd62be-c33d-5624-91be-03367e91d865', 'e.m.f. against time', 'C', false, 2),
('e5d6a726-ac0f-5477-af99-678357f36847', 'b0cd62be-c33d-5624-91be-03367e91d865', 'Flux linkage against time', 'D', true, 3),
('de7afd25-e154-57bc-89fb-9c96bfccef01', 'f09e5a82-2bae-54a1-b65f-e893a2e49b4f', 'It halves', 'A', false, 0),
('a26ae600-542c-5196-af29-abaeb41e4be8', 'f09e5a82-2bae-54a1-b65f-e893a2e49b4f', 'It doubles', 'B', true, 1),
('b10761df-be86-55dc-8fe2-ea9138b7aee6', 'f09e5a82-2bae-54a1-b65f-e893a2e49b4f', 'It stays the same', 'C', false, 2),
('cb5c815f-fdca-517e-a2bf-6d8a949b9e6f', 'f09e5a82-2bae-54a1-b65f-e893a2e49b4f', 'It quadruples', 'D', false, 3),
('9e9f77b2-7fab-5451-9d83-70cd19a3a876', 'c83c4051-f6f5-5eb9-9dc2-07e8a7b0c852', 'The size of the flux linkage', 'A', false, 0),
('4a1a6b9f-d766-5f6f-8118-1441d826b254', 'c83c4051-f6f5-5eb9-9dc2-07e8a7b0c852', 'The resistance of the coil only', 'B', false, 1),
('1c804889-eaf5-5a37-b6a0-bd79498adf36', 'c83c4051-f6f5-5eb9-9dc2-07e8a7b0c852', 'The rate at which the flux linkage changes', 'C', true, 2),
('f7ce8c89-a608-535e-8d49-ecc0c166c42c', 'c83c4051-f6f5-5eb9-9dc2-07e8a7b0c852', 'The direction of the field only', 'D', false, 3),
('2981b817-2a69-536c-9d23-5d5cca49f426', 'c17c3a27-8232-5f3c-a1d9-2c997e4d240a', 'When the change happens in the shortest time', 'A', true, 0),
('a8f09d6b-dd0b-50b8-8e0b-d25afba45a05', 'c17c3a27-8232-5f3c-a1d9-2c997e4d240a', 'When it happens in the longest time', 'B', false, 1),
('b50578ba-49e7-53c2-9c39-e01b4ea4340c', 'c17c3a27-8232-5f3c-a1d9-2c997e4d240a', 'It is the same in each case', 'C', false, 2),
('03c683ca-51e2-5824-afb6-d9437d361616', 'c17c3a27-8232-5f3c-a1d9-2c997e4d240a', 'When the flux linkage is largest', 'D', false, 3),
('0500d24b-d2f7-5832-bd37-fb5ab14397ef', '7c86a8e9-7e13-50cb-9c29-1cb56f0c5d49', 'It is a separate law that has nothing to do with flux', 'A', false, 0),
('7fbb825e-8a24-5ea0-8fb6-639538cdc75a', '7c86a8e9-7e13-50cb-9c29-1cb56f0c5d49', 'It applies only to coils', 'B', false, 1),
('65c52a17-af42-525a-9fa4-171f3d54e8cd', '7c86a8e9-7e13-50cb-9c29-1cb56f0c5d49', 'It gives the current, not the e.m.f.', 'C', false, 2),
('2b72a877-75d5-55e2-8d66-b1b41dae003e', '7c86a8e9-7e13-50cb-9c29-1cb56f0c5d49', 'It is Faraday''s law applied to the flux the rod sweeps out per second, BLv', 'D', true, 3),
('de2d1b58-9bec-5657-9678-60fa8fe11c12', '99759623-478f-5a7d-84f6-ff4da7c23a96', 'No e.m.f. is induced', 'A', false, 0),
('e112a5bf-fac8-5367-91c8-46753fb50154', '99759623-478f-5a7d-84f6-ff4da7c23a96', 'An e.m.f. is induced across the ends but no current flows', 'B', true, 1),
('ac35b969-a934-5165-bea1-eda2d4a479ca', '99759623-478f-5a7d-84f6-ff4da7c23a96', 'A current flows but there is no e.m.f.', 'C', false, 2),
